//************************ FNVconfig.h **************************// //**************** See RFC 9923 for details. ********************// /* Copyright (c) 2016-2025 IETF Trust and the persons * identified as authors of the code. All rights reserved. * See fnv-private.h for terms of use and redistribution. */
#ifndef _FNVconfig_H_ #define _FNVconfig_H_
/* * 説明: * このファイルは、FNV-1a 非暗号学的ハッシュアルゴリズムの * 構成のための ifdef を提供する。 */
/* FNV_64bitIntegers - システムが次をサポートする場合に定義する: * 32 ビット x 32 ビットの乗算を含む 64 ビット演算 * （乗算は 64 ビットの積を生成する）。未定義の場合は、 * 32 ビット演算がサポートされていると仮定する。 * これには 16 ビット x 16 ビットの乗算で * 32 ビットの結果を生成することが含まれる。 */
#include <stdint.h>
/* ターゲットで 64 ビット整数がサポートされているか確認する */
#ifdef UINT64_MAX #define FNV_64bitIntegers #else #undef FNV_64bitIntegers #endif
/* 以下により、上の構成の設定を * 上書きできる。 */
#ifdef FNV_TEST_PROGRAM # ifdef TEST_FNV_64bitIntegers # ifndef FNV_64bitIntegers # define FNV_64bitIntegers # endif # else # undef FNV_64bitIntegers # endif # ifndef FNV_64bitIntegers /* uint64_t が使われるとエラーになる */ # undef uint64_t # define uint64_t no_64_bit_integers # endif #endif
#endif /* _FNVconfig_H_ */

//********************** FNVErrorCodes.h **************************//
//**************** See RFC 9923 for details. **********************//
/* Copyright (c) 2016-2025 IETF Trust and the persons
 * identified as authors of the code.  All rights reserved.
 * See fnv-private.h for terms of use and redistribution.
 */

#ifndef _FNV_ErrCodes_
#define _FNV_ErrCodes_
//****************************************************************//
//
//  FNVxxxfile 関数を除くすべての FNV 関数は、
//    次のように整数を返す:
//       0 -> 成功
//      >0 -> 以下に挙げるエラー
//
enum {    /* 成功とエラー */
    fnvSuccess = 0,
    fnvNull,        // 1 ヌルポインターのパラメーター
    fnvStateError,  // 2 Result の後か Init の前に Input が呼ばれた
    fnvBadParam     // 3 不正なパラメーターが渡された
};
#endif /* _FNV_ErrCodes_ */

