#ifndef _FNV_PRIVATE_H_ #define _FNV_PRIVATE_H_
/* * 次のサイズの 6 つの FNV-1a ハッシュが定義されている: * FNV32 32 bits, 4 bytes * FNV64 64 bits, 8 bytes * FNV128 128 bits, 16 bytes * FNV256 256 bits, 32 bytes * FNV512 512 bits, 64 bytes * FNV1024 1024 bits, 128 bytes */
/* FNV（Fowler/Noll/Vo）非暗号学的ハッシュ関数 FNV-1a の * この実装で使用される内部用のもの。 * 外部の呼び出し元はこれらを知る必要はない。 */
enum { /* context->Computed の状態値の基数 */ FNVinited = 22, FNVcomputed = 76, FNVemptied = 220, FNVclobber = 122 /* テスト用の既知の不正な値 */ };
/* 長さごとに異なる状態値を保証するための差分 */ enum { FNV32state = 1, FNV64state = 3, FNV128state = 5, FNV256state = 7, FNV512state = 11, FNV1024state = 13 };
#endif /* _FNV_PRIVATE_H_ */

//*************************** FNV32.h ****************************// //****************** See RFC 9923 for details. *******************// /* Copyright (c) 2016-2025 IETF Trust and the persons * identified as authors of the code. All rights reserved. * See fnv-private.h for terms of use and redistribution. */
#ifndef _FNV32_H_ #define _FNV32_H_
/* * 説明: * このファイルは、32 ビット版の * FNV-1a 非暗号学的ハッシュアルゴリズムのヘッダーを提供する。 */
#include "FNVconfig.h" #include "FNVErrorCodes.h"
#include <stdint.h> #define FNV32size (32/8) #define FNV32basis 0x811C9DC5
/* ISO 標準の stdint.h ヘッダーファイルがない場合は、 * 次の型を typedef する必要がある: * * 型 意味 * uint32_t 符号なし 32 ビット整数 * uint8_t 符号なし 8 ビット整数（つまり unsigned char） */
/* * この構造体は FNV32 ハッシュのコンテキスト情報を保持する */ typedef struct FNV32context_s { int Computed; /* 状態 */ uint32_t Hash; } FNV32context;
/* 関数プロトタイプ: * * FNV32string: 終端のゼロを含まずに * ゼロ終端文字列をハッシュする * FNV32stringBasis: offset_basis パラメーターも受け取る * * FNV32block: 指定された長さのバイトベクターをハッシュする * FNV32blockBasis: offset_basis パラメーターも受け取る * * FNV32file: ファイルの内容をハッシュする * FNV32fileBasis: offset_basis パラメーターも受け取る * * FNV32init: FNV32 コンテキストを初期化する * FNV32initBasis: 与えられた基数で FNV32 コンテキストを * 初期化する（4 バイトのベクター） * FNV32blockin: 指定された長さのバイトベクターを取り込んでハッシュする * FNV32stringin: 終端のゼロを含まずに * ゼロ終端文字列を取り込んでハッシュする * FNV32filein: ファイルの内容を取り込んでハッシュする * FNV32result: ハッシュ値を返す * * 上の関数はハッシュを 4 バイトのベクターとして返し、 * 次の関数は 32 ビットの符号なし整数を返す: * * FNV32INTstring: 終端のゼロを含まずに * ゼロ終端文字列をハッシュする * FNV32INTstringBasis: offset_basis パラメーターも受け取る * * FNV32INTblock: 指定された長さのバイトベクターをハッシュする * FNV32INTblockBasis: offset_basis パラメーターも受け取る * * FNV32INTfile: ファイルの内容をハッシュする * FNV32INTfileBasis: offset_basis パラメーターも受け取る * * FNV32INTinitBasis: 与えられた基数で FNV32 コンテキストを * 初期化する（32 ビット整数） * FNV32INTresult: ハッシュ値を返す */
#ifdef __cplusplus extern "C" { #endif
/* FNV32 */ extern int FNV32INTstring ( const char *in, uint32_t * const out ); extern int FNV32INTstringBasis ( const char *in, uint32_t * const out, uint32_t basis ); extern int FNV32string ( const char *in, uint8_t out[FNV32size] ); extern int FNV32stringBasis ( const char *in, uint8_t out[FNV32size], const uint8_t basis[FNV32size] ); extern int FNV32INTblock ( const void *vin, long int length, uint32_t * const out ); extern int FNV32INTblockBasis ( const void *vin, long int length, uint32_t * const out, uint32_t basis ); extern int FNV32block ( const void *vin, long int length, uint8_t out[FNV32size] ); extern int FNV32blockBasis ( const void *vin, long int length, uint8_t out[FNV32size], const uint8_t basis[FNV32size] ); extern int FNV32INTfile ( const char *fname, uint32_t * const out ); extern int FNV32INTfileBasis ( const char *fname, uint32_t * const out, uint32_t basis ); extern int FNV32file ( const char *fname, uint8_t out[FNV32size] ); extern int FNV32fileBasis ( const char *fname, uint8_t out[FNV32size], const uint8_t basis[FNV32size] ); extern int FNV32init ( FNV32context * const ); extern int FNV32INTinitBasis ( FNV32context * const, uint32_t basis ); extern int FNV32initBasis ( FNV32context * const, const uint8_t basis[FNV32size] ); extern int FNV32blockin ( FNV32context * const, const void *vin, long int length ); extern int FNV32stringin ( FNV32context * const, const char *in ); extern int FNV32filein ( FNV32context * const, const char *fname ); extern int FNV32INTresult ( FNV32context * const, uint32_t * const out ); extern int FNV32result ( FNV32context * const, uint8_t out[FNV32size] );
#ifdef __cplusplus } #endif
#endif /* _FNV32_H_ */

//************************** FNV32.c **************************//
//**************** See RFC 9923 for details. ******************//
/* Copyright (c) 2016-2025 IETF Trust and the persons
 * identified as authors of the code.  All rights reserved.
 * See fnv-private.h for terms of use and redistribution.
 */

/* このコードは、FNV（Fowler/Noll/Vo）非暗号学的ハッシュ関数
 * FNV-1a を 32 ビットハッシュ用に実装する。
 */

#include <stdio.h>

#include "fnv-private.h"
#include "FNV32.h"

/* 32 ビットの FNV_prime = 2^24 + 2^8 + 0x93 */
#define FNV32prime 0x01000193

/* FNV32: ゼロを含まずにゼロ終端文字列をハッシュする
*****************************************************************/
int FNV32INTstring ( const char *in, uint32_t * const out ) {
    return FNV32INTstringBasis ( in, out, FNV32basis );
}   /* FNV32INTstring の終わり */

/* FNV32: ゼロを含まずにゼロ終端文字列をハッシュする
 * （非標準の基数を用いる）
*****************************************************************/
int FNV32INTstringBasis ( const char *in,
                          uint32_t * const out,
                          uint32_t basis ) {
    uint8_t     ch;

    if ( !in || !out )
        return fnvNull; /* 入力ポインターがヌル */
    while ( (ch = *in++) )
        basis = FNV32prime * ( basis ^ ch );
    *out = basis;
    return fnvSuccess;
}   /* FNV32INTstringBasis の終わり */

/* FNV32: ゼロを含まずにゼロ終端文字列をハッシュする
*****************************************************************/
int FNV32string ( const char *in, uint8_t out[FNV32size] ) {
    uint32_t    temp;
    uint8_t     ch;

    if ( !in || !out )
        return fnvNull; /* 入力ポインターがヌル */
    temp = FNV32basis;
    while ( (ch = *in++) )
        temp = FNV32prime * ( temp ^ ch );
    for ( int i=0; i<FNV32size; ++i )
        out[i] = ((uint8_t *)&temp)[i];
    return fnvSuccess;
}   /* FNV32string の終わり */

/* FNV32: ゼロを含まずにゼロ終端文字列をハッシュする
 * （非標準の基数を用いる）
*****************************************************************/
int FNV32stringBasis ( const char *in,
                       uint8_t out[FNV32size],
                       const uint8_t basis[FNV32size] ) {
    uint32_t temp;
    int i;
    uint8_t ch;

    if ( !in || !out || !basis )
        return fnvNull; /* 入力ポインターがヌル */
    temp = basis[0]+(basis[1]<<8)+(basis[2]<<16)+(basis[3]<<24);
    while ( (ch = *in++) )
        temp = FNV32prime * ( temp ^ ch );
    out[0] = temp & 0xFF;
    for ( i=1; i<FNV32size; ++i ) {
        temp >>= 8;
        out[i] = temp & 0xFF;
    }
    return fnvSuccess;
}   /* FNV32stringBasis の終わり */

/* FNV32: 長さ指定のブロックをハッシュし、整数を返す
 ****************************************************************/
int FNV32INTblock ( const void *vin,
                   long int length,
                   uint32_t * const out ) {
    return FNV32INTblockBasis ( vin, length, out, FNV32basis );
}   /* FNV32INTblock の終わり */

/* FNV32: 非標準の基数で長さ指定のブロックをハッシュする
 ****************************************************************/
int FNV32INTblockBasis ( const void *vin,
                 long int length,
                 uint32_t * const out,
                 uint32_t basis ) {
    const uint8_t *in = (const uint8_t*)vin;
    uint32_t temp;

    if ( !in || !out )
        return fnvNull; /* 入力ポインターがヌル */
    if ( length < 0 )
        return fnvBadParam;
    for ( temp = basis; length > 0; length-- )
        temp = FNV32prime * ( temp ^ *in++ );
    *out = temp;
    return fnvSuccess;
}   /* FNV32INTblockBasis の終わり */

/* FNV32: 長さ指定のブロックをハッシュし、4 バイトのベクターを返す
 ****************************************************************/
int FNV32block ( const void *vin,
                 long int length,
                 uint8_t out[FNV32size] ) {
    const uint8_t *in = (const uint8_t*)vin;
    uint32_t temp;

    if ( !in || !out )
        return fnvNull; /* 入力ポインターがヌル */
    if ( length < 0 )
        return fnvBadParam;
    for ( temp = FNV32basis; length > 0; length-- )
        temp = FNV32prime * ( temp ^ *in++ );
    for ( int i=0; i<FNV32size; ++i )
        out[i] = ((uint8_t *)&temp)[i];
    return fnvSuccess;
}   /* FNV32block の終わり */

/* FNV32: 非標準の基数で長さ指定のブロックをハッシュする
 ****************************************************************/
int FNV32blockBasis ( const void *vin,
                 long int length,
                 uint8_t out[FNV32size],
                 const uint8_t basis[FNV32size] ) {
    const uint8_t *in = (const uint8_t*)vin;
    uint32_t temp;

    if ( !in || !out || !basis )
        return fnvNull; /* 入力ポインターがヌル */
    if ( length < 0 )
        return fnvBadParam;
    temp = basis[0]+(basis[1]<<8)+(basis[2]<<16)+(basis[3]<<24);
    for ( ; length > 0; length-- )
        temp = FNV32prime * ( temp ^ *in++ );
    for ( int i=0; i<FNV32size; ++i )
        out[i] = ((uint8_t *)&temp)[i];
    return fnvSuccess;
}   /* FNV32blockBasis の終わり */

/* ファイルの内容をハッシュし、32 ビット整数を返す
 ******************************************************************/
int FNV32INTfile ( const char *fname,
                   uint32_t * const out ) {
    return FNV32INTfileBasis ( fname, out, FNV32basis );
}   /* FNV32INTfile の終わり */

/* ファイルの内容をハッシュし、32 ビット整数を返す
 * （非標準の基数を用いる）
 ******************************************************************/
int FNV32INTfileBasis ( const char *fname,
                        uint32_t * const out,
                        uint32_t basis ) {
    FNV32context e32Context;
    int error;

    if ( !out )
        return fnvNull;
    if ( (error = FNV32INTinitBasis ( &e32Context, basis )) )
        return error;
    if ( (error = FNV32filein ( &e32Context, fname )) )
        return error;
    return FNV32INTresult ( &e32Context, out );
}   /* FNV32INTfileBasis の終わり */

/* ファイルの内容をハッシュし、4 バイトのベクターを返す
 ******************************************************************/
int FNV32file ( const char *fname,
                uint8_t out[FNV32size] ) {
    FNV32context e32Context;
    int error;

    if ( !out )
        return fnvNull;
    if ( (error = FNV32init (&e32Context)) )
        return error;
    if ( (error = FNV32filein ( &e32Context, fname)) )
        return error;
    return FNV32result ( &e32Context, out );
}   /* FNV32file の終わり */

/* ファイルの内容をハッシュし、4 バイトのベクターを返す
 * （非標準の基数を用いる）
 ******************************************************************/
int FNV32fileBasis ( const char *fname,
                     uint8_t out[FNV32size],
                     const uint8_t basis[FNV32size] ) {
    FNV32context e32Context;
    int error;

    if ( !out )
        return fnvNull;
    if ( (error = FNV32initBasis (&e32Context, basis)) )
        return error;
    if ( (error = FNV32filein ( &e32Context, fname)) )
        return error;
    return FNV32result ( &e32Context, out );
}   /* FNV32fileBasis の終わり */

//**************************************************************
//       以下の初期化、入力、出力の関数群は、
//       FNV32 を逐次的に計算するためのもの
//**************************************************************

/* コンテキストを初期化する
 ***************************************************************/
int FNV32init ( FNV32context * const ctx ) {
    return FNV32INTinitBasis ( ctx, FNV32basis );
}   /* FNV32init の終わり */

/* 与えられた 32 ビット整数の基数でコンテキストを初期化する
 ***************************************************************/
int FNV32INTinitBasis ( FNV32context * const ctx,
                        uint32_t basis ) {
    if ( !ctx )
        return fnvNull;
    ctx->Hash = basis;
    ctx->Computed = FNVinited+FNV32state;
    return fnvSuccess;
}   /* FNV32INTinitBasis の終わり */

/* 与えられた 4 バイトのベクターの基数でコンテキストを初期化する
 ***************************************************************/
int FNV32initBasis ( FNV32context * const ctx,
                     const uint8_t basis[FNV32size] ) {
    if ( !ctx || !basis )
        return fnvNull;
    ctx->Hash =
        basis[0]+(basis[1]<<8)+(basis[2]<<16)+(basis[3]<<24);
    ctx->Computed = FNVinited+FNV32state;
    return fnvSuccess;
}   /* FNV32initBasis の終わり */

/* 長さ指定のブロックを取り込んでハッシュする
 ***************************************************************/
int FNV32blockin ( FNV32context * const ctx,
                   const void *vin,
                   long int length ) {
    const uint8_t *in = (const uint8_t*)vin;
    uint32_t temp;

    if ( !ctx || !in )
        return fnvNull;
    if ( length < 0 )
        return fnvBadParam;
    switch ( ctx->Computed ) {
        case FNVinited+FNV32state:
            ctx->Computed = FNVcomputed+FNV32state;
            break;
        case FNVcomputed+FNV32state:
            break;
        default:
            return fnvStateError;
    }
    for ( temp = ctx->Hash; length > 0; length-- )
        temp = FNV32prime * ( temp ^ *in++ );
    ctx->Hash = temp;
    return fnvSuccess;
}   /* FNV32blockin の終わり */

/* ゼロを含まずにゼロ終端文字列を取り込んでハッシュする
 ***************************************************************/
int FNV32stringin ( FNV32context * const ctx, const char *in ) {
    uint32_t temp;
    uint8_t ch;

    if ( !ctx || !in )
        return fnvNull;
    switch ( ctx->Computed ) {
        case FNVinited+FNV32state:
            ctx->Computed = FNVcomputed+FNV32state;
            break;
        case FNVcomputed+FNV32state:
            break;
        default:
            return fnvStateError;
    }
    temp = ctx->Hash;
    while ( (ch = (uint8_t)*in++) )
        temp = FNV32prime * ( temp ^ ch );
    ctx->Hash = temp;
    return fnvSuccess;
}   /* FNV32stringin の終わり */

/* ファイルの内容を取り込んでハッシュする
 ******************************************************************/
int FNV32filein ( FNV32context * const e32Context,
                  const char *fname ) {
    FILE *fp;
    long int i;
    char buf[1024];
    int error;

    if ( !e32Context || !fname )
        return fnvNull;
    switch ( e32Context->Computed ) {
        case FNVinited+FNV32state:
            e32Context->Computed = FNVcomputed+FNV32state;
            break;
        case FNVcomputed+FNV32state:
            break;
        default:
            return fnvStateError;
    }
    if ( ( fp = fopen ( fname, "rb") ) == NULL )
        return fnvBadParam;
    if ( (error = FNV32blockin ( e32Context, "", 0)) ) {
        fclose(fp);
        return error;
    }
    while ( ( i = fread ( buf, 1, sizeof(buf), fp ) ) > 0 )
        if ( (error = FNV32blockin ( e32Context, buf, i)) ) {
            fclose(fp);
            return error;
        }
    error = ferror(fp);
    fclose(fp);
    if (error) return fnvBadParam;
    return fnvSuccess;
}   /* FNV32filein の終わり */

/* ハッシュを整数として返す
 ***************************************************************/
int FNV32INTresult ( FNV32context * const ctx,
                     uint32_t * const out ) {
    if ( !ctx || !out )
        return fnvNull;
    if ( ctx->Computed != FNVcomputed+FNV32state )
        return fnvStateError;
    ctx->Computed = FNVemptied+FNV32state;
    *out = ctx->Hash;
    ctx->Hash = 0;
    return fnvSuccess;
}   /* FNV32INTresult の終わり */

/* ハッシュを 4 バイトのベクターとして返す
 ***************************************************************/
int FNV32result ( FNV32context * const ctx,
                  uint8_t out[FNV32size] ) {
    if ( !ctx || !out )
        return fnvNull;
    if ( ctx->Computed != FNVcomputed+FNV32state )
        return fnvStateError;
    ctx->Computed = FNVemptied+FNV32state;
    for ( int i=0; i<FNV32size; ++i )
        out[i] = ((uint8_t *)&ctx->Hash)[i];
    ctx->Hash = 0;
    return fnvSuccess;
}   /* FNV32result の終わり */

//*************************** FNV64.h ****************************//
//***************** See RFC 9923 for details. ********************//
/* Copyright (c) 2016-2025 IETF Trust and the persons
 * identified as authors of the code.  All rights reserved.
 * See fnv-private.h for terms of use and redistribution.
 */

#ifndef _FNV64_H_
#define _FNV64_H_

/*
 *  説明:
 *      このファイルは、64 ビット版の
 *      FNV-1a 非暗号学的ハッシュアルゴリズムのヘッダーを提供する。
 */

#include "FNVconfig.h"
#include "FNVErrorCodes.h"

#include <stdint.h>
#define FNV64size (64/8)
#ifdef FNV_64bitIntegers
#define FNV64basis 0xCBF29CE484222325
#endif

/* ISO 標準の stdint.h ヘッダーファイルがない場合は、
 * 次の型を typedef する必要がある:
 *
 *    型                意味
 *  uint64_t    符号なし 64 ビット整数（ifdef FNV_64bitIntegers）
 *  uint32_t    符号なし 32 ビット整数
 *  uint16_t    符号なし 16 ビット整数
 *  uint8_t     符号なし 8 ビット整数（つまり unsigned char）
 */

/*
 *  この構造体は FNV64 ハッシュのコンテキスト情報を保持する
 */
#ifdef FNV_64bitIntegers
    /* 64 ビット整数がサポートされている場合の版 */
typedef struct FNV64context_s {
        int Computed;  /* 状態 */
        uint64_t Hash;
} FNV64context;

#else
    /* 64 ビット整数がサポートされていない場合の版 */
typedef struct FNV64context_s {
        int Computed;  /* 状態 */
        uint16_t Hash[FNV64size/2];
} FNV64context;

#endif /* FNV_64bitIntegers */

/*  関数プロトタイプ:
 *
 *    FNV64string: 終端のゼロを含まずに
 *                 ゼロ終端文字列をハッシュする
 *    FNV64stringBasis: offset_basis パラメーターも受け取る
 *
 *    FNV64block: 指定された長さのバイトベクターをハッシュする
 *    FNV64blockBasis: offset_basis パラメーターも受け取る
 *
 *    FNV64file: ファイルの内容をハッシュする
 *    FNV64fileBasis: offset_basis パラメーターも受け取る
 *
 *    FNV64init: FNV64 コンテキストを初期化する
 *    FNV64initBasis: 与えられた基数で FNV64 コンテキストを
 *                    初期化する（8 バイトのベクター）
 *    FNV64blockin: 指定された長さのバイトベクターを取り込んでハッシュする
 *    FNV64stringin: 終端のゼロを含まずに
 *                   ゼロ終端文字列を取り込んでハッシュする
 *    FNV64filein: ファイルの内容を取り込んでハッシュする
 *    FNV64result: ハッシュ値を返す
 *
 * 上の関数はハッシュを 8 バイトのベクターとして返す。
 *    64 ビット整数がサポートされている場合、次の関数は
 *    64 ビット整数を返す。
 *
 *    FNV64INTstring: 終端のゼロを含まずに
 *                 ゼロ終端文字列をハッシュする
 *    FNV64INTstringBasis: offset_basis パラメーターも受け取る
 *
 *    FNV64INTblock: 指定された長さのバイトベクターをハッシュする
 *    FNV64INTblockBasis: offset_basis パラメーターも受け取る
 *
 *    FNV64INTfile: ファイルの内容をハッシュする
 *    FNV64INTfileBasis: offset_basis パラメーターも受け取る
 *
 *    FNV64INTinitBasis: 与えられた基数で FNV64 コンテキストを
 *                     初期化する（64 ビット整数）
 *    FNV64INTresult: ハッシュ値を返す
 */

#ifdef __cplusplus
extern "C" {
#endif

/* FNV64 */
extern int FNV64string ( const char *in,
                         uint8_t out[FNV64size] );
extern int FNV64stringBasis ( const char *in,
                              uint8_t out[FNV64size],
                              const uint8_t basis[FNV64size] );
extern int FNV64block ( const void *vin,
                        long int length,
                        uint8_t out[FNV64size] );
extern int FNV64blockBasis ( const void *vin,
                             long int length,
                             uint8_t out[FNV64size],
                             const uint8_t basis[FNV64size] );
extern int FNV64file ( const char * fname,
                       uint8_t out[FNV64size] );
extern int FNV64fileBasis ( const char * fname,
                            uint8_t out[FNV64size],
                            const uint8_t basis[FNV64size] );
extern int FNV64init ( FNV64context * const );
extern int FNV64initBasis ( FNV64context * const,
                            const uint8_t basis[FNV64size] );
extern int FNV64blockin ( FNV64context * const,
                          const void * vin,
                          long int length );
extern int FNV64stringin ( FNV64context * const,
                           const char * in );
extern int FNV64filein ( FNV64context * const,
                        const char *fname );
extern int FNV64result ( FNV64context * const,
                         uint8_t out[FNV64size] );

#ifdef FNV_64bitIntegers
  extern int FNV64INTstring ( const char *in,
                              uint64_t * const out );
  extern int FNV64INTstringBasis ( const char *in,
                                   uint64_t * const out,
                                   uint64_t basis );
  extern int FNV64INTblock ( const void *vin,
                             long int length,
                             uint64_t * const out );
  extern int FNV64INTblockBasis ( const void *vin,
                                  long int length,
                                  uint64_t * const out,
                                  uint64_t basis );
  extern int FNV64INTfile ( const char * fname,
                            uint64_t * const out );
  extern int FNV64INTfileBasis ( const char * fname,
                                 uint64_t * const out,
                                 uint64_t basis );
  extern int FNV64INTinitBasis ( FNV64context * const,
                                 uint64_t basis );
  extern int FNV64INTresult ( FNV64context * const,
                              uint64_t * const out );
#endif /* FNV_64bitIntegers */

#ifdef __cplusplus
}
#endif

#endif /* _FNV64_H_ */

