/* このファイルは、FNV（Fowler/Noll/Vo）非暗号学的ハッシュ関数
 * FNV-1a を 64 ビットハッシュ用に実装する。
 */

#include <stdio.h>

#include "FNVconfig.h"
#include "fnv-private.h"
#include "FNV64.h"

//*****************************************************************
// 32 ビット演算と 64 ビット演算で共通のコード
//*****************************************************************

/* ファイルの内容をハッシュし、バイトベクターを返す
 ******************************************************************/
int FNV64file ( const char *fname,
                uint8_t out[FNV64size] ) {
    FNV64context e64Context;
    int error;

    if ( !out )
        return fnvNull;
    if ( (error = FNV64init (&e64Context)) )
        return error;
    if ( (error = FNV64filein (&e64Context, fname)) )
        return error;
    return FNV64result (&e64Context, out);
}   /* FNV64file の終わり */

/* ファイルの内容をハッシュし、64 ビット整数を返す
 * （非標準の基数を用いる）
 ******************************************************************/
int FNV64fileBasis ( const char *fname,
                     uint8_t out[FNV64size],
                     const uint8_t basis[FNV64size] ) {
    FNV64context e64Context;
    int error;

    if ( !out )
        return fnvNull;
    if ( (error = FNV64initBasis (&e64Context, basis)) )
        return error;
    if ( (error = FNV64filein (&e64Context, fname)) )
        return error;
    return FNV64result (&e64Context, out);
}   /* FNV64fileBasis の終わり */

/* ファイルの内容を取り込んでハッシュする
 ******************************************************************/
int FNV64filein ( FNV64context * const e64Context,
                  const char *fname ) {
    FILE *fp;
    long int i;
    char buf[1024];
    int error;

    if ( !e64Context || !fname )
        return fnvNull;
    switch ( e64Context->Computed ) {
        case FNVinited+FNV64state:
            e64Context->Computed = FNVcomputed+FNV64state;
            break;
        case FNVcomputed+FNV64state:
            break;
        default:
            return fnvStateError;
    }
    if ( ( fp = fopen ( fname, "rb") ) == NULL )
        return fnvBadParam;
    if ( (error = FNV64blockin ( e64Context, "", 0)) ) {
        fclose(fp);
        return error;
    }
    while ( ( i = fread ( buf, 1, sizeof(buf), fp ) ) > 0 )
        if ( (error = FNV64blockin ( e64Context, buf, i)) ) {
            fclose(fp);
            return error;
        }
    error = ferror(fp);
    fclose(fp);
    if (error)
        return fnvBadParam;
    return fnvSuccess;
}

//*****************************************************************
// 64 ビット演算がある場合の版の開始
//*****************************************************************
#ifdef FNV_64bitIntegers

/* 64 ビットの FNV_prime = 2^40 + 2^8 + 0xb3 */
#define FNV64prime 0x00000100000001B3

/* FNV64: ゼロを含まずにゼロ終端文字列をハッシュする
 * 64 ビット整数にする（64 ビット）
 ******************************************************************/
int FNV64INTstring ( const char *in, uint64_t * const out ) {
    return FNV64INTstringBasis ( in, out, FNV64basis );
}   /* FNV64INTstring の終わり */

/* FNV64: ゼロを含まずにゼロ終端文字列をハッシュする
 * 非標準の基数で 64 ビット整数にする（64 ビット）
 ******************************************************************/
int FNV64INTstringBasis ( const char *in,
                          uint64_t * const out,
                          uint64_t basis ) {
    uint64_t temp;
    uint8_t ch;

    if ( !in || !out )
        return fnvNull; /* 入力ポインターがヌル */
    temp = basis;
    while ( (ch = *in++) )
        temp = FNV64prime * ( temp ^ ch );
    *out = temp;
    return fnvSuccess;
}   /* FNV64INTstringBasis の終わり */

/* FNV64: ゼロ終端文字列をハッシュして 64 ビット整数にする
 * バイトベクターにする（64 ビット）
 ******************************************************************/
int FNV64string ( const char *in, uint8_t out[FNV64size] ) {
    uint64_t temp;
    uint8_t ch;

    if ( !in || !out )
        return fnvNull; /* 入力ポインターがヌル */
    temp = FNV64basis;
    while ( (ch = *in++) )
        temp = FNV64prime * ( temp ^ ch );
    for ( int i=0; i<FNV64size; ++i )
        out[i] = ((uint8_t *)&temp)[i];
    return fnvSuccess;
}   /* FNV64string の終わり */

/* FNV64: ゼロ終端文字列をハッシュして 64 ビット整数にする
 * 非標準の基数でバイトベクターにする（64 ビット）
 ******************************************************************/
int FNV64stringBasis ( const char *in,
                       uint8_t out[FNV64size],
                       const uint8_t basis[FNV64size] ) {
    uint64_t temp;
    int i;
    uint8_t ch;

    if ( !in || !out || !basis )
        return fnvNull; /* 入力ポインターがヌル */
    temp = basis[7];
    for ( i = FNV64size-2; i>=0; --i )
        temp = (temp<<8) + basis[i];
    while ( (ch = *in++) )
        temp = FNV64prime * ( temp ^ ch );
    for ( i=0; i<FNV64size; ++i )
        out[i] = ((uint8_t *)&temp)[i];
    return fnvSuccess;
}   /* FNV64stringBasis の終わり */

/* FNV64: 長さ指定のブロックをハッシュして 64 ビット整数にする（64 ビット）
 ******************************************************************/
int FNV64INTblock ( const void *vin,
                    long int length,
                    uint64_t * const out ) {
    return FNV64INTblockBasis ( vin, length, out, FNV64basis );
}   /* FNV64INTblock の終わり */

/* FNV64: 長さ指定のブロックをハッシュして 64 ビット整数にする（64 ビット）
 * （非標準の基数を用いる）
 ******************************************************************/
int FNV64INTblockBasis ( const void *vin,
                         long int length,
                         uint64_t * const out,
                         uint64_t basis ) {
    const uint8_t *in = (const uint8_t*)vin;
    uint64_t temp;

    if ( !in || !out )
        return fnvNull;
               /* 入力ポインターまたは出力ポインターがヌル */
    if ( length < 0 )
        return fnvBadParam;
    for ( temp = basis; length > 0; length-- )
        temp = FNV64prime * ( temp ^ *in++ );
    *out = temp;
    return fnvSuccess;
}   /* FNV64INTblockBasis の終わり */

/* FNV64: 長さ指定のブロックをハッシュしてバイトベクターにする（64 ビット）
 ******************************************************************/
int FNV64block ( const void *vin,
                 long int length,
                 uint8_t out[FNV64size] ) {
    const uint8_t *in = (const uint8_t*)vin;
    uint64_t temp;

    if ( !in || !out )
        return fnvNull;
               /* 入力ポインターまたは出力ポインターがヌル */
    if ( length < 0 )
        return fnvBadParam;
    for ( temp = FNV64basis; length > 0; length-- )
        temp = FNV64prime * ( temp ^ *in++ );
    for ( int i=0; i<FNV64size; ++i )
        out[i] = ((uint8_t *)&temp)[i];
    return fnvSuccess;
}   /* FNV64block の終わり */

/* FNV64: 長さ指定のブロックをハッシュしてバイトベクターにする（64 ビット）
 * （非標準の基数を用いる）
 ******************************************************************/
int FNV64blockBasis ( const void *vin,
                      long int length,
                      uint8_t out[FNV64size],
                      const uint8_t basis[FNV64size] ) {
    const uint8_t *in = (const uint8_t*)vin;
    uint64_t temp;
    int i;

    if ( !in || !out || !basis )
        return fnvNull;
               /* 入力ポインターまたは出力ポインターがヌル */
    if ( length < 0 )
        return fnvBadParam;
    temp = basis[7];
    for ( i = FNV64size-2; i>=0; --i )
        temp = (temp<<8) + basis[i];
    for (; length > 0; length-- )
        temp = FNV64prime * ( temp ^ *in++ );
    for ( i=0; i<FNV64size; ++i )
        out[i] = ((uint8_t *)&temp)[i];
    return fnvSuccess;
}   /* FNV64blockBasis の終わり */

//*****************************************************************
//       以下の初期化、入力、出力の関数群は、
//       FNV64 を逐次的に計算するためのもの
//*****************************************************************

/* コンテキストを初期化する（64 ビット）
 ******************************************************************/
int FNV64init( FNV64context * const ctx ) {
    return FNV64INTinitBasis ( ctx, FNV64basis );
}       /* FNV64init の終わり */

/* 与えられた 64 ビット整数の基数でコンテキストを初期化する（64 ビット）
 ******************************************************************/
int FNV64INTinitBasis( FNV64context * const ctx, uint64_t basis ) {
    if ( !ctx )
        return fnvNull;
    ctx->Hash = basis;
    ctx->Computed = FNVinited+FNV64state;
    return fnvSuccess;
}   /* FNV64INTinitBasis の終わり */

/* 8 バイトのベクターの基数でコンテキストを初期化する（64 ビット）
 ******************************************************************/
int FNV64initBasis( FNV64context * const ctx,
                    const uint8_t basis[FNV64size] ) {
    if ( !ctx || !basis )
        return fnvNull;
    for ( int i=0; i<FNV64size; ++i )
        ((uint8_t *)&ctx->Hash)[i] = basis[i];
    ctx->Computed = FNVinited+FNV64state;
    return fnvSuccess;
}   /* FNV64initBasis の終わり */

/* 長さ指定のブロックを取り込んでハッシュする（64 ビット）
 ******************************************************************/
int FNV64blockin( FNV64context * const ctx,
                   const void *vin,
                   long int length ) {
    const uint8_t *in = (const uint8_t*)vin;
    uint64_t temp;

    if ( !ctx || !in )
        return fnvNull;
    if ( length < 0 )
        return fnvBadParam;
    switch ( ctx->Computed ) {
        case FNVinited+FNV64state:
            ctx->Computed = FNVcomputed+FNV64state;
            break;
        case FNVcomputed+FNV64state:
            break;
        default:
            return fnvStateError;
    }
    for ( temp = ctx->Hash; length > 0; length-- )
        temp = FNV64prime * ( temp ^ *in++ );
    ctx->Hash = temp;
    return fnvSuccess;
}   /* FNV64blockin の終わり */

/* ゼロを含まずにゼロ終端文字列を取り込んでハッシュする（64 ビット）
 ******************************************************************/
int FNV64stringin ( FNV64context * const ctx, const char *in ) {
    uint64_t        temp;
    uint8_t         ch;

    if ( !ctx || !in )
        return fnvNull;
    switch ( ctx->Computed ) {
        case FNVinited+FNV64state:
            ctx->Computed = FNVcomputed+FNV64state;
            break;
        case FNVcomputed+FNV64state:
            break;
        default:
             return fnvStateError;
    }
    temp = ctx->Hash;
    while ( (ch = (uint8_t)*in++) )
        temp = FNV64prime * ( temp ^ ch );
    ctx->Hash = temp;
    return fnvSuccess;
}   /* FNV64stringin の終わり */

/* ハッシュを 64 ビット整数として返す（64 ビット）
 ******************************************************************/
int FNV64INTresult ( FNV64context * const ctx,
                     uint64_t * const out ) {
    if ( !ctx || !out )
        return fnvNull;
    if ( ctx->Computed != FNVcomputed+FNV64state )
        return fnvStateError;
    ctx->Computed = FNVemptied+FNV64state;
    *out = ctx->Hash;
    ctx->Hash = 0;
    return fnvSuccess;
}   /* FNV64INTresult の終わり */

/* ハッシュを 8 バイトのベクターとして返す（64 ビット）
 ******************************************************************/
int FNV64result ( FNV64context * const ctx,
                 uint8_t out[FNV64size] ) {
    if ( !ctx || !out )
        return fnvNull;
    if ( ctx->Computed != FNVcomputed+FNV64state )
        return fnvStateError;
    ctx->Computed = FNVemptied+FNV64state;
    for ( int i=0; i<FNV64size; ++i )
        out[i] = ((uint8_t *)&ctx->Hash)[i];
    ctx->Hash = 0;
    return fnvSuccess;
}   /* FNV64result の終わり */

/* ファイルの内容をハッシュし、64 ビット整数を返す
 ******************************************************************/
int FNV64INTfile ( const char *fname,
                   uint64_t * const out ) {
    FNV64context e64Context;
    int error;

    if ( !out )
        return fnvNull;
    if ( (error = FNV64init (&e64Context)) )
        return error;
    if ( (error = FNV64filein (&e64Context, fname)) )
        return error;
    return FNV64INTresult ( &e64Context, out );
}   /* FNV64INTfile の終わり */

/* ファイルの内容をハッシュし、64 ビット整数を返す
 * （非標準の基数を用いる）
 ******************************************************************/
int FNV64INTfileBasis ( const char *fname,
                        uint64_t * const out,
                        uint64_t basis ) {
    FNV64context e64Context;
    int error;

    if ( !out )
        return fnvNull;
    if ( (error = FNV64INTinitBasis (&e64Context, basis)) )
        return error;
    if ( (error = FNV64filein (&e64Context, fname)) )
        return error;
    return FNV64INTresult ( &e64Context, out );
}   /* FNV64INTfileBasis の終わり */

//***************************************************************
// 64 ビット演算がある場合の版の終了
//***************************************************************
#else    /*  FNV_64bitIntegers */
//***************************************************************
// 32 ビット演算しかない場合の版の開始
//***************************************************************

/* 64 ビットの FNV_prime = 2^40 + 2^8 + 0xb3 */
/* #define FNV64prime 0x00000100000001B3 */
#define FNV64primeX 0x01B3
#define FNV64shift 8

/* FNV64: ゼロを含まずにゼロ終端文字列をハッシュする
 ******************************************************************/
int FNV64string ( const char *in, uint8_t out[FNV64size] ) {
    FNV64context ctx;
    int error;

    if ( (error = FNV64init (&ctx)) )
        return error;
    if ( (error = FNV64stringin (&ctx, in)) )
        return error;
    return FNV64result (&ctx, out);
}   /* FNV64string の終わり */

/* FNV64: ゼロを含まずにゼロ終端文字列をハッシュする
 * （非標準の offset_basis を用いる）
 ******************************************************************/
int FNV64stringBasis ( const char *in,
                  uint8_t out[FNV64size],
                  const uint8_t basis[FNV64size] ) {
    FNV64context ctx;
    int error;

    if ( (error = FNV64initBasis (&ctx, basis)) )
        return error;
    if ( (error = FNV64stringin (&ctx, in)) )
        return error;
    return FNV64result (&ctx, out);
}   /* FNV64stringBasis の終わり */

/* FNV64: 長さ指定のブロックをハッシュする
 ******************************************************************/
int FNV64block ( const void *vin,
                 long int length,
                 uint8_t out[FNV64size] ) {
    FNV64context ctx;
    int error;

    if ( (error = FNV64init (&ctx)) )
        return error;
    if ( (error = FNV64blockin (&ctx, vin, length)) )
        return error;
    return FNV64result (&ctx, out);
}   /* FNV64block の終わり */

/* FNV64: 非標準の offset_basis で長さ指定のブロックをハッシュする
 ******************************************************************/
int FNV64blockBasis ( const void *vin,
                      long int length,
                      uint8_t out[FNV64size],
                      const uint8_t basis[FNV64size] ) {
    FNV64context ctx;
    int error;

    if ( (error = FNV64initBasis (&ctx, basis)) )
        return error;
    if ( (error = FNV64blockin (&ctx, vin, length)) )
        return error;
    return FNV64result (&ctx, out);
}   /* FNV64blockBasis の終わり */

//*****************************************************************
//        以下の初期化、入力、出力の関数群は、
//        FNV64 を逐次的に計算するためのもの
//*****************************************************************

/* コンテキストを初期化する（32 ビット）
 ******************************************************************/
int FNV64init ( FNV64context * const ctx ) {
    if ( !ctx )
        return fnvNull;
    ctx->Hash[0] = 0xCBF2;
    ctx->Hash[1] = 0x9CE4;
    ctx->Hash[2] = 0x8422;
    ctx->Hash[3] = 0x2325;
    ctx->Computed = FNVinited+FNV64state;
    return fnvSuccess;
}   /* FNV64init の終わり */

/* 非標準の基数でコンテキストを初期化する（32 ビット）
 ******************************************************************/
int FNV64initBasis ( FNV64context * const ctx,
                     const uint8_t basis[FNV64size] ) {
    if ( !ctx || !basis )
        return fnvNull;
    for ( int i=0; i < FNV64size/2; ++i ) {
        uint32_t temp = *basis++;
        ctx->Hash[i] = ( temp<<8 ) + *basis++;
    }
    ctx->Computed = FNVinited+FNV64state;
    return fnvSuccess;
}   /* FNV64initBasis の終わり */

/* 長さ指定のブロックを取り込んでハッシュする（32 ビット）
 ******************************************************************/
int FNV64blockin ( FNV64context * const ctx,
                   const void *vin,
                   long int length ) {
    const uint8_t *in = (const uint8_t*)vin;
    uint32_t temp[FNV64size/2];
    uint32_t temp2[2];
    int i;

    if ( !ctx || !in )
        return fnvNull;
    if ( length < 0 )
        return fnvBadParam;
    switch ( ctx->Computed ) {
        case FNVinited+FNV64state:
            ctx->Computed = FNVcomputed+FNV64state;
            break;
        case FNVcomputed+FNV64state:
            break;
        default:
            return fnvStateError;
    }
    for ( i=0; i<FNV64size/2; ++i )
         temp[i] = ctx->Hash[i];
    for ( ; length > 0; length-- ) {
        /* temp = FNV64prime * ( temp ^ *in++ ); */
        temp[3] ^= *in++;
        temp2[1] = temp[3] << FNV64shift;
        temp2[0] = temp[2] << FNV64shift;
        for ( i=0; i<4; ++i )
            temp[i] *= FNV64primeX;
        temp[1] += temp2[1];
        temp[0] += temp2[0];
        for ( i=2; i>=0; --i ) {
            temp[i] += temp[i+1] >> 16;
            temp[i+1] &= 0xFFFF;
        }
    }
    for ( i=0; i<FNV64size/2; ++i )
        ctx->Hash[i] = temp[i];
    return fnvSuccess;
}   /* FNV64blockin の終わり */

/* ゼロを含まずにゼロ終端文字列を取り込んでハッシュする（32 ビット）
 ******************************************************************/
int FNV64stringin ( FNV64context * const ctx, const char *in ) {
    uint32_t temp[FNV64size/2];
    uint32_t temp2[2];
    int i;
    uint8_t ch;

    if ( !ctx || !in )
        return fnvNull;
    switch ( ctx->Computed ) {
        case FNVinited+FNV64state:
            ctx->Computed = FNVcomputed+FNV64state;
            break;
        case FNVcomputed+FNV64state:
            break;
        default:
             return fnvStateError;
    }
    for ( i=0; i<FNV64size/2; ++i )
         temp[i] = ctx->Hash[i];
    while ( ( ch = (uint8_t)*in++ ) ) {
        /* temp = FNV64prime * ( temp ^ ch ); */
        temp[3] ^= ch;
        temp2[1] = temp[3] << FNV64shift;
        temp2[0] = temp[2] << FNV64shift;
        for ( i=0; i<4; ++i )
            temp[i] *= FNV64primeX;
        temp[1] += temp2[1];
        temp[0] += temp2[0];
        for ( i=2; i>=0; --i ) {
            temp[i] += temp[i+1] >> 16;
            temp[i+1] &= 0xFFFF;
        }
    }
    for ( i=0; i<FNV64size/2; ++i )
        ctx->Hash[i] = temp[i];
    return fnvSuccess;
}   /* FNV64stringin の終わり */

/* ハッシュを返す（32 ビット）
 ******************************************************************/
int FNV64result ( FNV64context * const ctx,
                  uint8_t out[FNV64size] ) {
    if ( !ctx || !out )
        return fnvNull;
    if ( ctx->Computed != FNVcomputed+FNV64state )
        return fnvStateError;
    for ( int i=0; i<FNV64size/2; ++i ) {
        out[2*i] = ctx->Hash[i] >> 8;
        out[2*i+1] = ctx->Hash[i];
        ctx -> Hash[i] = 0;
        }
    ctx->Computed = FNVemptied+FNV64state;
    return fnvSuccess;
}   /* FNV64result の終わり */

#endif    /*  FNV_64bitIntegers */
