 */

#ifndef _FNV128_H_
#define _FNV128_H_

/*
 *  説明:
 *      このファイルは、128 ビット版の
 *      FNV-1a 非暗号学的ハッシュアルゴリズムのヘッダーを提供する。
 */

#include "FNVconfig.h"
#include "FNVErrorCodes.h"

#include <stdint.h>
#define FNV128size (128/8)

/* ISO 標準の stdint.h ヘッダーファイルがない場合は、
 * 次の型を typedef する必要がある:
 *
 *    型                意味
 *  uint64_t    符号なし 64 ビット整数（ifdef FNV_64bitIntegers）
 *  uint32_t    符号なし 32 ビット整数
 *  uint16_t    符号なし 16 ビット整数
 *  uint8_t     符号なし 8 ビット整数（つまり unsigned char）
 */

/*
 *  この構造体は FNV128 ハッシュのコンテキスト情報を保持する
 */
#ifdef FNV_64bitIntegers
    /* 64 ビット整数がサポートされている場合の版 */
typedef struct FNV128context_s {
        int Computed;  /* 状態 */
        uint32_t Hash[FNV128size/4];
} FNV128context;

#else
    /* 64 ビット整数がサポートされていない場合の版 */
typedef struct FNV128context_s {
        int Computed;  /* 状態 */
        uint16_t Hash[FNV128size/2];
} FNV128context;

#endif /* FNV_64bitIntegers */

/*  関数プロトタイプ:
 *
 *    FNV128string: 終端のゼロを含まずに
 *                  ゼロ終端文字列をハッシュする
 *    FNV128stringBasis: offset_basis パラメーターも受け取る
 *
 *    FNV128block: 指定された長さのバイトベクターをハッシュする
 *    FNV128blockBasis: offset_basis パラメーターも受け取る
 *
 *    FNV128file: ファイルの内容をハッシュする
 *    FNV128fileBasis: offset_basis パラメーターも受け取る
 *
 *    FNV128init: FNV128 コンテキストを初期化する
 *    FNV128initBasis: 与えられた基数で FNV128 コンテキストを
 *                     初期化する（16 バイトのベクター）
 *    FNV128blockin: 指定された長さのバイトベクターを取り込んでハッシュする
 *    FNV128stringin: 終端のゼロを含まずに
 *                    ゼロ終端文字列を取り込んでハッシュする
 *    FNV128filein: ファイルの内容を取り込んでハッシュする
 *    FNV128result: ハッシュ値を返す
 *
 *    ハッシュは 8 ビットの符号なし整数の配列として返される
 */

#ifdef __cplusplus
extern "C" {
#endif

/* FNV128 */
extern int FNV128string ( const char *in,
                          uint8_t out[FNV128size] );
extern int FNV128stringBasis ( const char *in,
                               uint8_t out[FNV128size],
                               const uint8_t basis[FNV128size] );
extern int FNV128block ( const void *vin,
                         long int length,
                         uint8_t out[FNV128size] );
extern int FNV128blockBasis ( const void *vin,
                              long int length,
                              uint8_t out[FNV128size],
                              const uint8_t basis[FNV128size] );
extern int FNV128file ( const char *fname,
                        uint8_t out[FNV128size] );
extern int FNV128fileBasis ( const char *fname,
                             uint8_t out[FNV128size],
                             const uint8_t basis[FNV128size] );
extern int FNV128init ( FNV128context * const );
extern int FNV128initBasis ( FNV128context * const,
                             const uint8_t basis[FNV128size] );
extern int FNV128blockin ( FNV128context * const,
                           const void *vin,
                           long int length );
extern int FNV128stringin ( FNV128context * const,
                            const char *in );
extern int FNV128filein ( FNV128context * const,
                         const char *fname );
extern int FNV128result ( FNV128context * const,
                          uint8_t out[FNV128size] );

#ifdef __cplusplus
}
#endif

#endif /* _FNV128_H_ */

//**************************** FNV128.c **************************//
//******************* See RFC 9923 for details. ******************//
/* Copyright (c) 2016-2025 IETF Trust and the persons
 * identified as authors of the code.  All rights reserved.
 * See fnv-private.h for terms of use and redistribution.
 */

/* このファイルは、FNV（Fowler/Noll/Vo）非暗号学的ハッシュ関数
 * FNV-1a を 128 ビットハッシュ用に実装する。
 */

#include <stdio.h>

#include "FNVconfig.h"
#include "fnv-private.h"
#include "FNV128.h"

//*****************************************************************
//  64 ビットと 32 ビットの整数モードで共通のコード
//*****************************************************************

/* FNV128: ゼロを含まずにゼロ終端文字列をハッシュする
 ******************************************************************/
int FNV128string ( const char *in, uint8_t out[FNV128size] ) {
    FNV128context ctx;
    int error;

    if ( (error = FNV128init ( &ctx )) )
        return error;
    if ( (error = FNV128stringin ( &ctx, in )) )
        return error;
    return FNV128result (&ctx, out);
}   /* FNV128string の終わり */

/* FNV128: ゼロを含まずにゼロ終端文字列をハッシュする
 ******************************************************************/
int FNV128stringBasis ( const char *in,
                        uint8_t out[FNV128size],
                        const uint8_t basis[FNV128size] ) {
    FNV128context ctx;
    int error;

    if ( (error = FNV128initBasis ( &ctx, basis )) )
        return error;
    if ( (error = FNV128stringin ( &ctx, in )) )
        return error;
    return FNV128result ( &ctx, out );
}   /* FNV128stringBasis の終わり */

/* FNV128: 長さ指定のブロックをハッシュする（64/32 ビット）
 ******************************************************************/
int FNV128block ( const void *vin,
                  long int length,
                  uint8_t out[FNV128size] ) {
    FNV128context ctx;
    int error;

    if ( (error = FNV128init ( &ctx )) )
        return error;
    if ( (error = FNV128blockin ( &ctx, vin, length )) )
        return error;
    return FNV128result ( &ctx, out );
}   /* FNV128block の終わり */

/* FNV128: 長さ指定のブロックをハッシュする（64/32 ビット）
 ******************************************************************/
int FNV128blockBasis ( const void *vin,
                       long int length,
                       uint8_t out[FNV128size],
                       const uint8_t basis[FNV128size] ) {
    FNV128context ctx;
    int error;

    if ( (error = FNV128initBasis ( &ctx, basis )) )
        return error;
    if ( (error = FNV128blockin ( &ctx, vin, length )) )
        return error;
    return FNV128result ( &ctx, out );
}   /* FNV128blockBasis の終わり */

/* ファイルの内容をハッシュする
 ******************************************************************/
int FNV128file ( const char *fname,
                 uint8_t out[FNV128size] ) {
    FNV128context e128Context;
    int error;

    if ( !out )
        return fnvNull;
    if ( (error = FNV128init (&e128Context)) )
        return error;
    if ( (error = FNV128filein (&e128Context, fname)) )
        return error;
    return FNV128result ( &e128Context, out );
}   /* FNV128file の終わり */

/* 非標準の基数でファイルの内容をハッシュする
 ******************************************************************/
int FNV128fileBasis ( const char *fname,
                      uint8_t out[FNV128size],
                      const uint8_t basis[FNV128size] ) {
    FNV128context e128Context;
    int error;

    if ( !out )
        return fnvNull;
    if ( (error = FNV128initBasis (&e128Context, basis)) )
        return error;
    if ( (error = FNV128filein (&e128Context, fname)) )
        return error;
    return FNV128result ( &e128Context, out );
}   /* FNV128fileBasis の終わり */

/* ファイルの内容を取り込んでハッシュする
 ******************************************************************/
int FNV128filein ( FNV128context * const e128Context,
                   const char *fname ) {
    FILE *fp;
    long int i;
    char buf[1024];
    int error;

    if ( !e128Context || !fname )
        return fnvNull;
    switch ( e128Context->Computed ) {
        case FNVinited+FNV128state:
            e128Context->Computed = FNVcomputed+FNV128state;
            break;
        case FNVcomputed+FNV128state:
            break;
        default:
            return fnvStateError;
    }
    if ( ( fp = fopen ( fname, "rb") ) == NULL )
        return fnvBadParam;
    if ( (error = FNV128blockin ( e128Context, "", 0)) ) {
        fclose(fp);
        return error;
    }
    while ( ( i = fread ( buf, 1, sizeof(buf), fp ) ) > 0 )
        if ( (error = FNV128blockin ( e128Context, buf, i)) ) {
            fclose(fp);
            return error;
        }
    error = ferror(fp);
    fclose(fp);
    if (error) return fnvBadParam;
    return fnvSuccess;
}   /* FNV128filein の終わり */

//*****************************************************************
// 64 ビット演算がある場合の版の開始
//*****************************************************************
#ifdef FNV_64bitIntegers

/* 128 ビットの FNV_prime = 2^88 + 2^8 + 0x3b */
/* 0x00000000 01000000 00000000 0000013B */
#define FNV128primeX 0x013B
#define FNV128shift 24

//*****************************************************************
//         以下の初期化、入力、出力の関数群は、
//         FNV128 を逐次的に計算するためのもの
//*****************************************************************/

/* コンテキストを初期化する（64 ビット）
 ******************************************************************/
int FNV128init ( FNV128context * const ctx ) {
    const uint32_t FNV128basis[FNV128size/4] =
        { 0x6C62272E, 0x07BB0142, 0x62B82175, 0x6295C58D };

    if ( !ctx )
        return fnvNull;
    for ( int i=0; i<4; ++i )
        ctx->Hash[i] = FNV128basis[i];
    ctx->Computed = FNVinited+FNV128state;
    return fnvSuccess;
}   /* FNV128init の終わり */

/* 16 バイトのベクターの基数でコンテキストを初期化する（64 ビット）
 ******************************************************************/
int FNV128initBasis ( FNV128context * const ctx,
                      const uint8_t basis[FNV128size] ) {
   if ( !ctx || !basis )
        return fnvNull;
    for ( int i=0; i < FNV128size/4; ++i ) {
        uint32_t temp = *basis++<<24;
        temp += *basis++<<16;
        temp += *basis++<<8;
        ctx->Hash[i] = temp + *basis++;
    }
    ctx->Computed = FNVinited+FNV128state;
    return fnvSuccess;
}   /* FNV128initBasis の終わり */

/* 長さ指定のブロックを取り込んでハッシュする（64 ビット）
 ******************************************************************/
int FNV128blockin ( FNV128context * const ctx,
                    const void *vin,
                    long int length ) {
    const uint8_t *in = (const uint8_t*)vin;
    uint64_t temp[FNV128size/4];
    uint64_t temp2[2];
    int i;

    if ( !ctx || !in )
        return fnvNull;
    if ( length < 0 )
        return fnvBadParam;
    switch ( ctx->Computed ) {
        case FNVinited+FNV128state:
            ctx->Computed = FNVcomputed+FNV128state;
            break;
        case FNVcomputed+FNV128state:
            break;
        default:
            return fnvStateError;
    }
    for ( i=0; i<FNV128size/4; ++i )
         temp[i] = ctx->Hash[i];
    for ( ; length > 0; length-- ) {
        /* temp = FNV128prime * ( temp ^ *in++ ); */
        temp[FNV128size/4-1] ^= *in++;
        temp2[1] = temp[3] << FNV128shift;
        temp2[0] = temp[2] << FNV128shift;
        for ( i=0; i < FNV128size/4; ++i )
            temp[i] *= FNV128primeX;
        temp[1] += temp2[1];
        temp[0] += temp2[0];
        for ( i = 3; i > 0; --i ) {
            temp[i-1] += temp[i] >> 32;
            temp[i] &= 0xFFFFFFFF;
        }
    }
    for ( i=0; i<FNV128size/4; ++i )
        ctx->Hash[i] = (uint32_t)temp[i];
    return fnvSuccess;
}   /* FNV128blockin の終わり */

/* ゼロを含まずにゼロ終端文字列を取り込んでハッシュする（64 ビット）
 ******************************************************************/
int FNV128stringin ( FNV128context * const ctx, const char *in ) {
    uint64_t temp[FNV128size/4];
    uint64_t temp2[2];
    int i;
    uint8_t ch;

    if ( !ctx || !in )
        return fnvNull;
    switch ( ctx->Computed ) {
        case FNVinited+FNV128state:
            ctx->Computed = FNVcomputed+FNV128state;
            break;
        case FNVcomputed+FNV128state:
            break;
        default:
            return fnvStateError;
    }
    for ( i=0; i<FNV128size/4; ++i )
         temp[i] = ctx->Hash[i];
    while ( ( ch = (uint8_t)*in++ ) ) {
        /* temp = FNV128prime * ( temp ^ ch ); */
        temp[3] ^= ch;
        temp2[1] = temp[3] << FNV128shift;
        temp2[0] = temp[2] << FNV128shift;
        for ( i=0; i < FNV128size/4; ++i )
            temp[i] *= FNV128primeX;
        temp[1] += temp2[1];
        temp[0] += temp2[0];
        for ( i = 3; i > 0; --i ) {
            temp[i-1] += temp[i] >> 32;
            temp[i] &= 0xFFFFFFFF;
        }
    }
    for ( i=0; i<FNV128size/4; ++i )
        ctx->Hash[i] = (uint32_t)temp[i];
    return fnvSuccess;
}   /* FNV128stringin の終わり */

/* ハッシュを 16 バイトのベクターとして返す（64 ビット）
 ******************************************************************/
int FNV128result ( FNV128context * const ctx,
                   uint8_t out[FNV128size] ) {
    if ( !ctx || !out )
        return fnvNull;
    if ( ctx->Computed != FNVcomputed+FNV128state )
        return fnvStateError;
    for ( int i=0; i<FNV128size/4; ++i ) {
        out[4*i] = ctx->Hash[i] >> 24;
        out[4*i+1] = ctx->Hash[i] >> 16;
        out[4*i+2] = ctx->Hash[i] >> 8;
        out[4*i+3] = ctx->Hash[i];
        ctx -> Hash[i] = 0;
    }
    ctx->Computed = FNVemptied+FNV128state;
    return fnvSuccess;
}   /* FNV128result の終わり */

//****************************************************************
// 64 ビット演算がある場合の版の終了
//****************************************************************
#else    /*  FNV_64bitIntegers */
//****************************************************************
// 32 ビット演算しかない場合の版の開始
//****************************************************************

/* 128 ビットの FNV_prime = 2^88 + 2^8 + 0x3b */
/* 0x00000000 01000000 00000000 0000013B */
#define FNV128primeX 0x013B
#define FNV128shift 8

//*****************************************************************
//         以下の初期化、入力、出力の関数群は、
//         FNV128 を逐次的に計算するためのもの
//*****************************************************************

/* コンテキストを初期化する（32 ビット）
 ******************************************************************/
int FNV128init ( FNV128context * const ctx ) {
    const uint16_t FNV128basis[FNV128size/2] =
             { 0x6C62, 0x272E, 0x07BB, 0x0142,
               0x62B8, 0x2175, 0x6295, 0xC58D };

    if ( !ctx )
        return fnvNull;
    for ( int i=0; i<FNV128size/2; ++i )
        ctx->Hash[i] = FNV128basis[i];
    ctx->Computed = FNVinited+FNV128state;
    return fnvSuccess;
}   /* FNV128init の終わり */

/* 16 バイトのベクターの基数でコンテキストを初期化する（32 ビット）
 ******************************************************************/
int FNV128initBasis ( FNV128context * const ctx,
                      const uint8_t basis[FNV128size] ) {
    if ( !ctx || !basis )
        return fnvNull;
    for ( int i=0; i < FNV128size/2; ++i ) {
        uint32_t temp = *basis++;
        ctx->Hash[i] = ( temp<<8 ) + *basis++;
    }
    ctx->Computed = FNVinited+FNV128state;
    return fnvSuccess;
}   /* FNV128initBasis の終わり */

/* 長さ指定のブロックを取り込んでハッシュする（32 ビット）
 *****************************************************************/
int FNV128blockin ( FNV128context * const ctx,
                    const void *vin,
                    long int length ) {
    const uint8_t *in = (const uint8_t*)vin;
    uint32_t temp[FNV128size/2];
    uint32_t temp2[3];
    int i;

    if ( !ctx || !in )
        return fnvNull;
    if ( length < 0 )
        return fnvBadParam;
    switch ( ctx->Computed ) {
        case FNVinited+FNV128state:
            ctx->Computed = FNVcomputed+FNV128state;
            break;
        case FNVcomputed+FNV128state:
            break;
        default:
            return fnvStateError;
    }
    for ( i=0; i < FNV128size/2; ++i )
         temp[i] = ctx->Hash[i];
    for ( ; length > 0; length-- ) {
        /* temp = FNV128prime * ( temp ^ *in++ ); */
        temp[FNV128size/2-1] ^= *in++;
        for ( i=2; i >= 0; --i )
            temp2[i] = temp[i+5] << FNV128shift;
        for ( i=0; i < (FNV128size/2); ++i )
            temp[i] *= FNV128primeX;
        for ( i=2; i >= 0; --i )
            temp[i] += temp2[i];
        for ( i=FNV128size/2-1; i>0; --i ) {
            temp[i-1] += temp[i] >> 16;
            temp[i] &= 0xFFFF;
        }
    }
    for ( i=0; i < FNV128size/2; ++i )
        ctx->Hash[i] = temp[i];
    return fnvSuccess;
}   /* FNV128blockin の終わり */

/* ゼロを含まずにゼロ終端文字列を取り込んでハッシュする（32 ビット）
 ******************************************************************/
int FNV128stringin ( FNV128context * const ctx, const char *in ) {
    uint32_t temp[FNV128size/2];
    uint32_t temp2[3];
    int i;
    uint8_t ch;

    if ( !ctx || !in )
        return fnvNull;
    switch ( ctx->Computed ) {
        case FNVinited+FNV128state:
            ctx->Computed = FNVcomputed+FNV128state;
            break;
        case FNVcomputed+FNV128state:
            break;
        default:
             return fnvStateError;
    }
    for ( i=0; i < FNV128size/2; ++i )
         temp[i] = ctx->Hash[i];
    while ( (ch = (uint8_t)*in++) ) {
        /* temp = FNV128prime * ( temp ^ *in++ ); */
        temp[FNV128size/2-1] ^= ch;
        for ( i=2; i >= 0; --i )
            temp2[i] = temp[i+5] << FNV128shift;
        for ( i=0; i<(FNV128size/2); ++i )
            temp[i] *= FNV128primeX;
        for ( i=2; i >= 0; --i )
            temp[i] += temp2[i];
        for ( i=FNV128size/2-1; i>0; --i ) {
            temp[i-1] += temp[i] >> 16;
            temp[i] &= 0xFFFF;
        }
    }
    for ( i=0; i < FNV128size/2; ++i )
        ctx->Hash[i] = temp[i];
    return fnvSuccess;
}   /* FNV128stringin の終わり */

/* ハッシュを返す（32 ビット）
 ******************************************************************/
int FNV128result ( FNV128context * const ctx,
                   uint8_t out[FNV128size] ) {
    if ( !ctx || !out )
        return fnvNull;
    if ( ctx->Computed != FNVcomputed+FNV128state )
        return fnvStateError;
    for ( int i=0; i<FNV128size/2; ++i ) {
        out[2*i] = ctx->Hash[i] >> 8;
        out[2*i+1] = ctx->Hash[i];
        ctx -> Hash[i] = 0;
    }
    ctx->Computed = FNVemptied+FNV128state;
    return fnvSuccess;
}   /* FNV128result の終わり */

#endif    /*  FNV_64bitIntegers */
