#ifndef _FNV256_H_
#define _FNV256_H_

/*
 *  説明:
 *      このファイルは、256 ビット版の
 *      FNV-1a 非暗号学的ハッシュアルゴリズムのヘッダーを提供する。
 */

#include "FNVconfig.h"
#include "FNVErrorCodes.h"

#include <stdint.h>
#define FNV256size (256/8)

/* ISO 標準の stdint.h ヘッダーファイルがない場合は、
 * 次の型を typedef する必要がある:
 *
 *    型                意味
 *  uint64_t    符号なし 64 ビット整数（ifdef FNV_64bitIntegers）
 *  uint32_t    符号なし 32 ビット整数
 *  uint16_t    符号なし 16 ビット整数
 *  uint8_t     符号なし 8 ビット整数（つまり unsigned char）
 */

/*
 *  この構造体は FNV256 ハッシュのコンテキスト情報を保持する
 */
#ifdef FNV_64bitIntegers
    /* 64 ビット整数がサポートされている場合の版 */
typedef struct FNV256context_s {
        int Computed;  /* 状態 */
        uint32_t Hash[FNV256size/4];
} FNV256context;

#else
    /* 64 ビット整数がサポートされていない場合の版 */
typedef struct FNV256context_s {
        int Computed;  /* 状態 */
        uint16_t Hash[FNV256size/2];
} FNV256context;

#endif /* FNV_64bitIntegers */

/*  関数プロトタイプ:
 *
 *    FNV256string: 終端のゼロを含まずに
 *                  ゼロ終端文字列をハッシュする
 *    FNV256stringBasis: offset_basis パラメーターも受け取る
 *
 *    FNV256block: 指定された長さのバイトベクターをハッシュする
 *    FNV256blockBasis: offset_basis パラメーターも受け取る
 *
 *    FNV256file: ファイルの内容をハッシュする
 *    FNV256fileBasis: offset_basis パラメーターも受け取る
 *
 *    FNV256init: FNV256 コンテキストを初期化する
 *    FNV256initBasis: 与えられた基数で FNV256 コンテキストを
 *                     初期化する（32 バイトのベクター）
 *    FNV256blockin: 指定された長さのバイトベクターを取り込んでハッシュする
 *    FNV256stringin: 終端のゼロを含まずに
 *                    ゼロ終端文字列を取り込んでハッシュする
 *    FNV256filein: ファイルの内容を取り込んでハッシュする
 *    FNV256result: ハッシュ値を返す
 *
 *    ハッシュは 8 ビットの符号なし整数の配列として返される
 */

#ifdef __cplusplus
extern "C" {
#endif

/* FNV256 */
extern int FNV256string ( const char *in,
                          uint8_t out[FNV256size] );
extern int FNV256stringBasis ( const char *in,
                               uint8_t out[FNV256size],
                               const uint8_t basis[FNV256size] );
extern int FNV256block ( const void *vin,
                         long int length,
                         uint8_t out[FNV256size] );
extern int FNV256blockBasis ( const void *vin,
                              long int length,
                              uint8_t out[FNV256size],
                              const uint8_t basis[FNV256size] );
extern int FNV256file ( const char *fname,
                        uint8_t out[FNV256size] );
extern int FNV256fileBasis ( const char *fname,
                             uint8_t out[FNV256size],
                             const uint8_t basis[FNV256size] );
extern int FNV256init ( FNV256context * const );
extern int FNV256initBasis ( FNV256context * const,
                             const uint8_t basis[FNV256size] );
extern int FNV256blockin ( FNV256context * const,
                           const void *vin,
                           long int length );
extern int FNV256stringin ( FNV256context * const,
                            const char *in );
extern int FNV256filein ( FNV256context * const,
                         const char *fname );
extern int FNV256result ( FNV256context * const,
                          uint8_t out[FNV256size] );

#ifdef __cplusplus
}
#endif

#endif /* _FNV256_H_ */

