/* このファイルは、FNV（Fowler/Noll/Vo）非暗号学的ハッシュ関数
 * FNV-1a を 256 ビットハッシュ用に実装する。
 */

#include <stdio.h>

#include "fnv-private.h"
#include "FNV256.h"

//*****************************************************************
//  64 ビットと 32 ビットの整数モードで共通のコード
//*****************************************************************

/* FNV256: ゼロを含まずにゼロ終端文字列をハッシュする
 ******************************************************************/
int FNV256string ( const char *in, uint8_t out[FNV256size] ) {
    FNV256context ctx;
    int error;

    if ( (error = FNV256init ( &ctx )) )
        return error;
    if ( (error = FNV256stringin ( &ctx, in )) )
        return error;
    return FNV256result ( &ctx, out );
}   /* FNV256string の終わり */

/* FNV256: ゼロを含まずにゼロ終端文字列をハッシュする
 * （非標準の基数を用いる）
 ******************************************************************/
int FNV256stringBasis ( const char *in,
                        uint8_t out[FNV256size],
                        const uint8_t basis[FNV256size] ) {
    FNV256context ctx;
    int error;

    if ( (error = FNV256initBasis ( &ctx, basis )) )
        return error;
    if ( (error = FNV256stringin ( &ctx, in )) )
        return error;
    return FNV256result ( &ctx, out );
}   /* FNV256stringBasis の終わり */

/* FNV256: 長さ指定のブロックをハッシュする（64/32 ビット）
 ******************************************************************/
int FNV256block ( const void *vin,
                  long int length,
                  uint8_t out[FNV256size] ) {
    FNV256context ctx;
    int error;

    if ( (error = FNV256init ( &ctx )) )
        return error;
    if ( (error = FNV256blockin ( &ctx, vin, length)) )
        return error;
    return FNV256result ( &ctx, out );
}   /* FNV256block の終わり */

/* FNV256: 長さ指定のブロックをハッシュする（64/32 ビット）
 * （非標準の基数を用いる）
 ******************************************************************/
int FNV256blockBasis ( const void *vin,
                       long int length,
                       uint8_t out[FNV256size],
                       const uint8_t basis[FNV256size] ) {
    FNV256context ctx;
    int error;

    if ( (error = FNV256initBasis ( &ctx, basis )) )
        return error;
    if ( (error = FNV256blockin ( &ctx, vin, length)) )
        return error;
    return FNV256result ( &ctx, out );
}   /* FNV256blockBasis の終わり */

/* ファイルの内容をハッシュする
 ******************************************************************/
int FNV256file ( const char *fname,
                        uint8_t out[FNV256size] ) {
    FNV256context e256Context;
    int error;

    if ( !out )
        return fnvNull;
    if ( (error = FNV256init (&e256Context)) )
        return error;
    if ( (error = FNV256filein (&e256Context, fname)) )
        return error;
    return FNV256result ( &e256Context, out );
}   /* FNV256file の終わり */

/* 非標準の基数でファイルの内容をハッシュする
 ******************************************************************/
int FNV256fileBasis ( const char *fname,
                      uint8_t out[FNV256size],
                      const uint8_t basis[FNV256size]) {
    FNV256context e256Context;
    int error;

    if ( !out )
        return fnvNull;
    if ( (error = FNV256initBasis (&e256Context, basis)) )
        return error;
    if ( (error = FNV256filein (&e256Context, fname)) )
        return error;
    return FNV256result ( &e256Context, out );
}   /* FNV256fileBasis の終わり */

/* ファイルの内容を取り込んでハッシュする
 ******************************************************************/
int FNV256filein ( FNV256context * const e256Context,
                   const char *fname ) {
    FILE *fp;
    long int i;
    char buf[1024];
    int error;

    if ( !e256Context || !fname )
        return fnvNull;
    switch ( e256Context->Computed ) {
        case FNVinited+FNV256state:
            e256Context->Computed = FNVcomputed+FNV256state;
            break;
        case FNVcomputed+FNV256state:
            break;
        default:
             return fnvStateError;
    }
    if ( ( fp = fopen ( fname, "rb") ) == NULL )
        return fnvBadParam;
    if ( (error = FNV256blockin ( e256Context, "", 0)) ) {
        fclose(fp);
        return error;
    }
    while ( ( i = fread ( buf, 1, sizeof(buf), fp ) ) > 0 )
        if ( (error = FNV256blockin ( e256Context, buf, i)) ) {
            fclose(fp);
            return error;
        }
    error = ferror(fp);
    fclose(fp);
    if (error) return fnvBadParam;
    return fnvSuccess;
}   /* FNV256filein の終わり */

//*****************************************************************
// 64 ビット演算がある場合の版の開始
//*****************************************************************
#ifdef FNV_64bitIntegers

/* 256 ビットの FNV_prime = 2^168 + 2^8 + 0x63 */
/* 0x0000000000000000 0000010000000000
     0000000000000000 0000000000000163 */
#define FNV256primeX 0x0163
#define FNV256shift 8

//*****************************************************************
//         以下の初期化、入力、出力の関数群は、
//         FNV256 を逐次的に計算するためのもの
//*****************************************************************

/* コンテキストを初期化する（64 ビット）
 ******************************************************************/
int FNV256init ( FNV256context * const ctx ) {
    const uint32_t FNV256basis[FNV256size/4] = {
             0xDD268DBC, 0xAAC55036, 0x2D98C384, 0xC4E576CC,
             0xC8B15368, 0x47B6BBB3, 0x1023B4C8, 0xCAEE0535 };

    if ( !ctx )
        return fnvNull;
    for ( int i=0; i<FNV256size/4; ++i )
        ctx->Hash[i] = FNV256basis[i];
    ctx->Computed = FNVinited+FNV256state;
    return fnvSuccess;
}   /* FNV256init の終わり */

/* 32 バイトのベクターの基数でコンテキストを初期化する（64 ビット）
 * （非標準の基数を用いる）
 ******************************************************************/
int FNV256initBasis ( FNV256context * const ctx,
                      const uint8_t basis[FNV256size] ) {
    if ( !ctx || !basis )
        return fnvNull;
    for ( int i=0; i < FNV256size/4; ++i ) {
        uint32_t temp = *basis++<<24;
        temp += *basis++<<16;
        temp += *basis++<<8;
        ctx->Hash[i] = temp + *basis++;
    }
    ctx->Computed = FNVinited+FNV256state;
    return fnvSuccess;
}   /* FNV256initBasis の終わり */

/* 長さ指定のブロックを取り込んでハッシュする（64 ビット）
 ******************************************************************/
int FNV256blockin ( FNV256context * const ctx,
                    const void *vin,
                    long int length ) {
    const uint8_t *in = (const uint8_t*)vin;
    uint64_t temp[FNV256size/4];
    uint64_t temp2[3];
    int i;

    if ( !ctx || !in )
        return fnvNull;
    if ( length < 0 )
        return fnvBadParam;
    switch ( ctx->Computed ) {
        case FNVinited+FNV256state:
            ctx->Computed = FNVcomputed+FNV256state;
            break;
        case FNVcomputed+FNV256state:
            break;
        default:
            return fnvStateError;
    }
    for ( i=0; i<FNV256size/4; ++i )
         temp[i] = ctx->Hash[i];
    for ( ; length > 0; length-- ) {
        /* temp = FNV256prime * ( temp ^ *in++ ); */
        temp[FNV256size/4-1] ^= *in++;
        for ( i=2; i >= 0; --i )
            temp2[i] = temp[i+5] << FNV256shift;
        for ( i=0; i < FNV256size/4; ++i )
            temp[i] *= FNV256primeX;
        for ( i=2; i >= 0; --i )
            temp[i] += temp2[i];
        for ( i=FNV256size/4-1; i>0; --i ) {
            temp[i-1] += temp[i] >> 32;
            temp[i] &= 0xFFFFFFFF;
        }
    }
    for ( i=0; i<FNV256size/4; ++i )
        ctx->Hash[i] = (uint32_t)temp[i];
    return fnvSuccess;
}   /* FNV256blockin の終わり */

/* ゼロを含まずにゼロ終端文字列を取り込んでハッシュする（64 ビット）
 ******************************************************************/
int FNV256stringin ( FNV256context * const ctx, const char *in ) {
    uint64_t temp[FNV256size/4];
    uint64_t temp2[3];
    int i;
    uint8_t ch;

    if ( !ctx || !in )
        return fnvNull;
    switch ( ctx->Computed ) {
        case FNVinited+FNV256state:
            ctx->Computed = FNVcomputed+FNV256state;
            break;
        case FNVcomputed+FNV256state:
            break;
        default:
            return fnvStateError;
    }
    for ( i=0; i<FNV256size/4; ++i )
         temp[i] = ctx->Hash[i];
    while ( (ch = (uint8_t)*in++) ) {
        /* temp = FNV256prime * ( temp ^ ch ); */
        temp[FNV256size/4-1] ^= ch;
        for ( i=2; i >= 0; --i )
            temp2[i] = temp[i+5] << FNV256shift;
        for ( i=0; i<FNV256size/4; ++i )
            temp[i] *= FNV256primeX;
        for ( i=2; i >= 0; --i )
            temp[i] += temp2[i];
        for ( i=FNV256size/4-1; i>0; --i ) {
            temp[i-1] += temp[i] >> 32;
            temp[i] &= 0xFFFFFFFF;
        }
    }
    for ( i=0; i<FNV256size/4; ++i )
        ctx->Hash[i] = (uint32_t)temp[i];
    return fnvSuccess;
}   /* FNV256stringin の終わり */

/* ハッシュを 8 バイトのベクターとして返す（64 ビット）
 ******************************************************************/
int FNV256result ( FNV256context * const ctx,
                   uint8_t out[FNV256size] ) {
    if ( !ctx || !out )
        return fnvNull;
    if ( ctx->Computed != FNVcomputed+FNV256state )
        return fnvStateError;
    for ( int i=0; i<FNV256size/4; ++i ) {
        out[4*i] = ctx->Hash[i] >> 24;
        out[4*i+1] = ctx->Hash[i] >> 16;
        out[4*i+2] = ctx->Hash[i] >> 8;
        out[4*i+3] = ctx->Hash[i];
        ctx -> Hash[i] = 0;
    }
    ctx->Computed = FNVemptied+FNV256state;
    return fnvSuccess;
}   /* FNV256result の終わり */

//****************************************************************
// 64 ビット演算がある場合の版の終了
//****************************************************************
#else    /*  FNV_64bitIntegers */
//****************************************************************
// 32 ビット演算しかない場合の版の開始
//****************************************************************

/* 256 ビットの FNV_prime = 2^168 + 2^8 + 0x63 */
/* 0x00000000 00000000 00000100 00000000
     00000000 00000000 00000000 00000163 */
#define FNV256primeX 0x0163
#define FNV256shift 8

//****************************************************************
//       以下の初期化、入力、出力の関数群は、
//       FNV256 を逐次的に計算するためのもの
//****************************************************************

/* コンテキストを初期化する（32 ビット）
 *****************************************************************/
int FNV256init ( FNV256context * const ctx ) {
    const uint16_t FNV256basis[FNV256size/2] = {
0xDD26, 0x8DBC, 0xAAC5, 0x5036, 0x2D98, 0xC384, 0xC4E5, 0x76CC,
0xC8B1, 0x5368, 0x47B6, 0xBBB3, 0x1023, 0xB4C8, 0xCAEE, 0x0535 };

    if ( !ctx )
        return fnvNull;
    for ( int i=0; i<FNV256size/2; ++i )
        ctx->Hash[i] = FNV256basis[i];
    ctx->Computed = FNVinited+FNV256state;
    return fnvSuccess;
}   /* FNV256init の終わり */

/* 32 バイトのベクターの基数でコンテキストを初期化する（32 ビット）
 ******************************************************************/
int FNV256initBasis ( FNV256context * const ctx,
                      const uint8_t basis[FNV256size] ) {
    if ( !ctx || !basis )
        return fnvNull;
    for ( int i=0; i < FNV256size/2; ++i ) {
        uint32_t temp = *basis++;
        ctx->Hash[i] = ( temp<<8 ) + *basis++;
    }
    ctx->Computed = FNVinited+FNV256state;
    return fnvSuccess;
}   /* FNV256initBasis の終わり */

/* 長さ指定のブロックを取り込んでハッシュする（32 ビット）
 *****************************************************************/
int FNV256blockin ( FNV256context * const ctx,
                    const void *vin,
                    long int length ) {
    const uint8_t *in = (const uint8_t*)vin;
    uint32_t temp[FNV256size/2];
    uint32_t temp2[6];
    int i;

    if ( !ctx || !in )
        return fnvNull;
    if ( length < 0 )
        return fnvBadParam;
    switch ( ctx->Computed ) {
        case FNVinited+FNV256state:
            ctx->Computed = FNVcomputed+FNV256state;
            break;
        case FNVcomputed+FNV256state:
            break;
        default:
            return fnvStateError;
    }
    for ( i=0; i<FNV256size/2; ++i )
        temp[i] = ctx->Hash[i];
    for ( ; length > 0; length-- ) {
        /* temp = FNV256prime * ( temp ^ *in++ ); */
        temp[FNV256size/2-1] ^= *in++;
        for ( i=0; i<6; ++i )
            temp2[5-i] = temp[FNV256size/2-1-i] << FNV256shift;
        for ( i=0; i<FNV256size/2; ++i )
            temp[i] *= FNV256primeX;
        for ( i=0; i<6; ++i )
            temp[i] += temp2[i];
        for ( i=FNV256size/2-1; i>0; --i ) {
            temp[i-1] += temp[i] >> 16;
            temp[i] &= 0xFFFF;
        }
    }
    for ( i=0; i<FNV256size/2; ++i )
        ctx->Hash[i] = temp[i];
    return fnvSuccess;
}   /* FNV256blockin の終わり */

/* ゼロを含まずにゼロ終端文字列を取り込んでハッシュする（32 ビット）
 ******************************************************************/
int FNV256stringin ( FNV256context * const ctx, const char *in ) {
    uint32_t temp[FNV256size/2];
    uint32_t temp2[6];
    int i;
    uint8_t ch;

    if ( !ctx || !in )
        return fnvNull;
    switch ( ctx->Computed ) {
        case FNVinited+FNV256state:
            ctx->Computed = FNVcomputed+FNV256state;
            break;
        case FNVcomputed+FNV256state:
            break;
        default:
             return fnvStateError;
    }
    for ( i=0; i<FNV256size/2; ++i )
         temp[i] = ctx->Hash[i];
    while ( ( ch = (uint8_t)*in++ ) ) {
        /* temp = FNV256prime * ( temp ^ *in++ ); */
        temp[FNV256size/2-1] ^= ch;
        for ( i=0; i<6; ++i )
            temp2[5-i] = temp[FNV256size/2-1-i] << FNV256shift;
        for ( i=0; i<FNV256size/2; ++i )
            temp[i] *= FNV256primeX;
        for ( i=0; i<6; ++i )
            temp[i] += temp2[i];
        for ( i=FNV256size/2-1; i>0; --i ) {
            temp[i-1] += temp[i] >> 16;
            temp[i] &= 0xFFFF;
        }
    }
    for ( i=0; i<FNV256size/2; ++i )
        ctx->Hash[i] = temp[i];
    return fnvSuccess;
}   /* FNV256stringin の終わり */

/* ハッシュを返す（32 ビット）
 *****************************************************************/
int FNV256result ( FNV256context * const ctx,
                   uint8_t out[FNV256size] ) {
    if ( !ctx || !out )
        return fnvNull;
    if ( ctx->Computed != FNVcomputed+FNV256state )
        return fnvStateError;
    for ( int i=0; i<FNV256size/2; ++i ) {
        out[2*i] = ctx->Hash[i] >> 8;
        out[2*i+1] = ctx->Hash[i];
        ctx->Hash[i] = 0;
    }
    ctx->Computed = FNVemptied+FNV256state;
    return fnvSuccess;
}   /* FNV256result の終わり */

#endif    /*  FNV_64bitIntegers */
//****************************************************************
// 32 ビット演算しかない場合の版の終了
//****************************************************************

