#ifndef _FNV512_H_
#define _FNV512_H_

/*
 *  説明:
 *      このファイルは、512 ビット版の
 *      FNV-1a 非暗号学的ハッシュアルゴリズムのヘッダーを提供する。
 */

#include "FNVconfig.h"
#include "FNVErrorCodes.h"

#include <stdint.h>
#define FNV512size (512/8)

/* ISO 標準の stdint.h ヘッダーファイルがない場合は、
 * 次の型を typedef する必要がある:
 *
 *    型                意味
 *  uint64_t    符号なし 64 ビット整数（ifdef FNV_64bitIntegers）
 *  uint32_t    符号なし 32 ビット整数
 *  uint16_t    符号なし 16 ビット整数
 *  uint8_t     符号なし 8 ビット整数（つまり unsigned char）
 */

/*
 *  この構造体は FNV512 ハッシュのコンテキスト情報を保持する
 */
#ifdef FNV_64bitIntegers
    /* 64 ビット整数がサポートされている場合の版 */
typedef struct FNV512context_s {
        int Computed;  /* 状態 */
        uint32_t Hash[FNV512size/4];
} FNV512context;

#else
    /* 64 ビット整数がサポートされていない場合の版 */
typedef struct FNV512context_s {
        int Computed;  /* 状態 */
        uint16_t Hash[FNV512size/2];
} FNV512context;

#endif /* FNV_64bitIntegers */

/*  関数プロトタイプ:
 *
 *    FNV512string: 終端のゼロを含まずに
 *                  ゼロ終端文字列をハッシュする
 *    FNV512stringBasis: offset_basis パラメーターも受け取る
 *
 *    FNV512block: 指定された長さのバイトベクターをハッシュする
 *    FNV512blockBasis: offset_basis パラメーターも受け取る
 *
 *    FNV512file: ファイルの内容をハッシュする
 *    FNV512fileBasis: offset_basis パラメーターも受け取る
 *
 *    FNV512init: FNV512 コンテキストを初期化する
 *    FNV512initBasis: 与えられた基数で FNV512 コンテキストを
 *                     初期化する（64 バイトのベクター）
 *    FNV512blockin: 指定された長さのバイトベクターを取り込んでハッシュする
 *    FNV512stringin: 終端のゼロを含まずに
 *                    ゼロ終端文字列を取り込んでハッシュする
 *    FNV512filein: ファイルの内容を取り込んでハッシュする
 *    FNV512result: ハッシュ値を返す
 *
 *    ハッシュは 8 ビットの符号なし整数の配列として返される
 */

#ifdef __cplusplus
extern "C" {
#endif

/* FNV512 */
extern int FNV512string ( const char *in,
                          uint8_t out[FNV512size] );
extern int FNV512stringBasis ( const char *in,
                               uint8_t out[FNV512size],
                               const uint8_t basis[FNV512size] );
extern int FNV512block ( const void *vin,
                         long int length,
                         uint8_t out[FNV512size] );
extern int FNV512blockBasis ( const void *vin,
                              long int length,
                              uint8_t out[FNV512size],
                              const uint8_t basis[FNV512size] );
extern int FNV512file ( const char *fname,
                        uint8_t out[FNV512size] );
extern int FNV512fileBasis ( const char *fname,
                             uint8_t out[FNV512size],
                             const uint8_t basis[FNV512size] );
extern int FNV512init ( FNV512context * const );
extern int FNV512initBasis ( FNV512context * const,
                             const uint8_t basis[FNV512size] );
extern int FNV512blockin ( FNV512context * const,
                           const void *vin,
                           long int length );
extern int FNV512stringin ( FNV512context * const,
                            const char *in );
extern int FNV512filein ( FNV512context * const,
                          const char *fname );
extern int FNV512result ( FNV512context * const,
                          uint8_t out[FNV512size] );

#ifdef __cplusplus
}
