/* このファイルは、FNV（Fowler/Noll/Vo）非暗号学的ハッシュ関数
 * FNV-1a を 512 ビットハッシュ用に実装する。
 */

#include <stdio.h>

#include "fnv-private.h"
#include "FNV512.h"

//*****************************************************************
//  64 ビットと 32 ビットの整数モードで共通のコード
//*****************************************************************

/* FNV512: ゼロを含まずにゼロ終端文字列をハッシュする
 ******************************************************************/
int FNV512string ( const char *in, uint8_t out[FNV512size] ) {
    FNV512context ctx;
    int error;

    if ( (error = FNV512init ( &ctx )) )
        return error;
    if ( (error = FNV512stringin ( &ctx, in )) )
        return error;
    return FNV512result ( &ctx, out );
}   /* FNV512string の終わり */

/* FNV512: ゼロを含まずにゼロ終端文字列をハッシュする
 * （非標準の基数を用いる）
 ******************************************************************/
int FNV512stringBasis ( const char *in,
                        uint8_t out[FNV512size],
                        const uint8_t basis[FNV512size] ) {
    FNV512context ctx;
    int error;

    if ( (error = FNV512initBasis ( &ctx, basis )) )
        return error;
    if ( (error = FNV512stringin ( &ctx, in )) )
        return error;
    return FNV512result ( &ctx, out );
}   /* FNV512stringBasis の終わり */

/* FNV512: 長さ指定のブロックをハッシュする（64/32 ビット）
 ******************************************************************/
int FNV512block ( const void *vin,
                  long int length,
                  uint8_t out[FNV512size] ) {
    FNV512context ctx;
    int error;

    if ( (error = FNV512init ( &ctx )) )
        return error;
    if ( (error = FNV512blockin ( &ctx, vin, length)) )
        return error;
    return FNV512result ( &ctx, out );
}   /* FNV512block の終わり */

/* FNV512: 長さ指定のブロックをハッシュする（64/32 ビット）
 * （非標準の基数を用いる）
 ******************************************************************/
int FNV512blockBasis ( const void *vin,
                       long int length,
                       uint8_t out[FNV512size],
                       const uint8_t basis[FNV512size] ) {
    FNV512context ctx;
    int error;

    if ( (error = FNV512initBasis ( &ctx, basis )) )
        return error;
    if ( (error = FNV512blockin ( &ctx, vin, length)) )
        return error;
    return FNV512result ( &ctx, out );
}   /* FNV512blockBasis の終わり */

/* ファイルの内容をハッシュする
 ******************************************************************/
int FNV512file ( const char *fname,
                 uint8_t out[FNV512size] ) {
    FNV512context e512Context;
    int error;

    if ( !out )
        return fnvNull;
    if ( (error = FNV512init (&e512Context)) )
        return error;
    if ( (error = FNV512filein (&e512Context, fname)) )
        return error;
    return FNV512result ( &e512Context, out );
}   /* FNV512file の終わり */

/* 非標準の基数でファイルの内容をハッシュする
 ******************************************************************/
int FNV512fileBasis ( const char *fname,
                      uint8_t out[FNV512size],
                      const uint8_t basis[FNV512size] ) {
    FNV512context e512Context;
    int error;

    if ( !out )
        return fnvNull;
    if ( (error = FNV512initBasis (&e512Context, basis)) )
        return error;
    if ( (error = FNV512filein (&e512Context, fname)) )
        return error;
    return FNV512result ( &e512Context, out );
}   /* FNV512fileBasis の終わり */

/* ファイルの内容を取り込んでハッシュする
 ******************************************************************/
int FNV512filein ( FNV512context * const e512Context,
                    const char *fname ) {
    FILE *fp;
    long int i;
    char buf[1024];
    int error;

    if ( !e512Context || !fname )
        return fnvNull;
    switch ( e512Context->Computed ) {
        case FNVinited+FNV512state:
            e512Context->Computed = FNVcomputed+FNV512state;
            break;
        case FNVcomputed+FNV512state:
            break;
        default:
             return fnvStateError;
    }
    if ( ( fp = fopen ( fname, "rb") ) == NULL )
        return fnvBadParam;
    if ( (error = FNV512blockin ( e512Context, "", 0)) ) {
        fclose(fp);
        return error;
    }
    while ( ( i = fread ( buf, 1, sizeof(buf), fp ) ) > 0 )
        if ( (error=FNV512blockin ( e512Context, buf, i)) ) {
            fclose(fp);
            return error;
        }
    error = ferror(fp);
    fclose(fp);
    if (error) return fnvBadParam;
    return fnvSuccess;
}   /* FNV512filein の終わり */

//*****************************************************************
// 64 ビット演算がある場合の版の開始
//*****************************************************************
#ifdef FNV_64bitIntegers

/* 512 ビットの FNV_prime = 2^344 + 2^8 + 0x57 =
   0x0000000000000000 0000000000000000
     0000000001000000 0000000000000000
     0000000000000000 0000000000000000
     0000000000000000 0000000000000157 */
#define FNV512primeX 0x0157
#define FNV512shift 24

//*****************************************************************
//         以下の初期化、入力、出力の関数群は、
//         FNV512 を逐次的に計算するためのもの
//*****************************************************************

/* コンテキストを初期化する（64 ビット）
 ******************************************************************/
int FNV512init ( FNV512context * const ctx ) {
    const uint32_t FNV512basis[FNV512size/4] = {
         0xB86DB0B1, 0x171F4416, 0xDCA1E50F, 0x309990AC,
         0xAC87D059, 0xC9000000, 0x00000000, 0x00000D21,
         0xE948F68A, 0x34C192F6, 0x2EA79BC9, 0x42DBE7CE,
         0x18203641, 0x5F56E34B, 0xAC982AAC, 0x4AFE9FD9 };

    if ( !ctx )
        return fnvNull;
    for ( int i=0; i<FNV512size/4; ++i )
        ctx->Hash[i] = FNV512basis[i];
    ctx->Computed = FNVinited+FNV512state;
    return fnvSuccess;
}   /* FNV512init の終わり */

/* 64 バイトのベクターの基数でコンテキストを初期化する（64 ビット）
 ******************************************************************/
int FNV512initBasis ( FNV512context * const ctx,
                      const uint8_t basis[FNV512size] ) {
     if ( !ctx || !basis )
        return fnvNull;
    for ( int i=0; i < FNV512size/4; ++i ) {
        uint32_t temp = *basis++<<24;
        temp += *basis++<<16;
        temp += *basis++<<8;
        ctx->Hash[i] = temp + *basis++;
    }
    ctx->Computed = FNVinited+FNV512state;
    return fnvSuccess;
}   /* FNV512initBasis の終わり */

/* 長さ指定のブロックを取り込んでハッシュする（64 ビット）
 ******************************************************************/
int FNV512blockin ( FNV512context * const ctx,
                    const void *vin,
                    long int length ) {
    const uint8_t *in = (const uint8_t*)vin;
    uint64_t temp[FNV512size/4];
    uint64_t temp2[6];
    int i;

    if ( !ctx || !in )
        return fnvNull;
    if ( length < 0 )
        return fnvBadParam;
    switch ( ctx->Computed ) {
        case FNVinited+FNV512state:
            ctx->Computed = FNVcomputed+FNV512state;
            break;
        case FNVcomputed+FNV512state:
            break;
        default:
            return fnvStateError;
    }
    for ( i=0; i<FNV512size/4; ++i )
         temp[i] = ctx->Hash[i];  // temp にコピーする
    for ( ; length > 0; length-- ) {
        /* temp = FNV512prime * ( temp ^ *in++ ); */
        temp[FNV512size/4-1] ^= *in++;
        for ( i=0; i<6; ++i )
            temp2[5-i] = temp[FNV512size/4-1-i] << FNV512shift;
        for ( i=0; i<FNV512size/4; ++i )
            temp[i] *= FNV512primeX;
        for ( i=0; i<6; ++i )
            temp[i] += temp2[i];
        for ( i=FNV512size/4-1; i>0; --i ) {
            temp[i-1] += temp[i] >> 32; // 桁上がりを伝播する
            temp[i] &= 0xFFFFFFFF;
        }
    }   /* for length の終わり */
    for ( i=0; i<FNV512size/4; ++i )
        ctx->Hash[i] = (uint32_t)temp[i];  // hash に書き戻す
    return fnvSuccess;
}   /* FNV512blockin の終わり */

/* ゼロを含まずにゼロ終端文字列を取り込んでハッシュする（64 ビット）
 ******************************************************************/
int FNV512stringin ( FNV512context * const ctx, const char *in ) {
    uint64_t temp[FNV512size/4];
    uint64_t temp2[6];
    int i;
    uint8_t ch;

    if ( !ctx || !in )
        return fnvNull;
    switch ( ctx->Computed ) {
        case FNVinited+FNV512state:
            ctx->Computed = FNVcomputed+FNV512state;
            break;
        case FNVcomputed+FNV512state:
            break;
        default:
            return fnvStateError;
    }
    for ( i=0; i<FNV512size/4; ++i )
         temp[i] = ctx->Hash[i];  // temp にコピーする
    while ( (ch = (uint8_t)*in++) ) {
        /* temp = FNV512prime * ( temp ^ ch ); */
        temp[FNV512size/4-1] ^= ch;
        for ( i=0; i<6; ++i )
            temp2[5-i] = temp[FNV512size/4-1-i] << FNV512shift;
        for ( i=0; i<FNV512size/4; ++i )
            temp[i] *= FNV512primeX;
        for ( i=0; i<6; ++i )
            temp[i] += temp2[i];
        for ( i=FNV512size/4-1; i>0; --i ) {
            temp[i-1] += temp[i] >> 32; // 桁上がりを伝播する
            temp[i] &= 0xFFFFFFFF;
        }
    }
    for ( i=0; i<FNV512size/4; ++i )
        ctx->Hash[i] = (uint32_t)temp[i];  // hash に書き戻す
    return fnvSuccess;
}   /* FNV512stringin の終わり */

/* ハッシュを返す（64 ビット）
 ******************************************************************/
int FNV512result ( FNV512context * const ctx,
                   uint8_t out[FNV512size] ) {
    if ( !ctx || !out )
        return fnvNull;
    if ( ctx->Computed != FNVcomputed+FNV512state )
        return fnvStateError;
    for ( int i=0; i<FNV512size/4; ++i ) {
        out[4*i] = ctx->Hash[i] >> 24;
        out[4*i+1] = ctx->Hash[i] >> 16;
        out[4*i+2] = ctx->Hash[i] >> 8;
        out[4*i+3] = ctx->Hash[i];
        ctx -> Hash[i] = 0;
    }
    ctx->Computed = FNVemptied+FNV512state;
    return fnvSuccess;
}   /* FNV512result の終わり */

//*****************************************************************
// 64 ビット演算がある場合の版の終了
//*****************************************************************
#else    /*  FNV_64bitIntegers */
//*****************************************************************
// 32 ビット演算しかない場合の版の開始
//*****************************************************************

/* 512 ビットの FNV_prime = 2^344 + 2^8 + 0x57 =
   0x00000000 00000000 00000000 00000000
     00000000 01000000 00000000 00000000
     00000000 00000000 00000000 00000000
     00000000 00000000 00000000 00000157 */
#define FNV512primeX 0x0157
#define FNV512shift 8

//*****************************************************************
//         以下の初期化、入力、出力の関数群は、
//         FNV512 を逐次的に計算するためのもの
//*****************************************************************

/* コンテキストを初期化する（32 ビット）
 ******************************************************************/
int FNV512init ( FNV512context * const ctx ) {
    const uint16_t FNV512basis[FNV512size/2] = {
0xB86D, 0xB0B1, 0x171F, 0x4416, 0xDCA1, 0xE50F, 0x3099, 0x90AC,
0xAC87, 0xD059, 0xC900, 0x0000, 0x0000, 0x0000, 0x0000, 0x0D21,
0xE948, 0xF68A, 0x34C1, 0x92F6, 0x2EA7, 0x9BC9, 0x42DB, 0xE7CE,
0x1820, 0x3641, 0x5F56, 0xE34B, 0xAC98, 0x2AAC, 0x4AFE, 0x9FD9 };

    if ( !ctx )
        return fnvNull;
    for ( int i=0; i<FNV512size/2; ++i )
        ctx->Hash[i] = FNV512basis[i];
    ctx->Computed = FNVinited+FNV512state;
    return fnvSuccess;
}   /* FNV512init の終わり */

/* 64 バイトのベクターの基数でコンテキストを初期化する（32 ビット）
 ******************************************************************/
int FNV512initBasis ( FNV512context * const ctx,
                      const uint8_t basis[FNV512size] ) {
    if ( !ctx || !basis )
        return fnvNull;
    for ( int i=0; i < FNV512size/2; ++i ) {
        uint32_t temp = *basis++;
        ctx->Hash[i] = ( temp<<8 ) + *basis++;
    }
    ctx->Computed = FNVinited+FNV512state;
    return fnvSuccess;
}   /* FNV512initBasis の終わり */

/* 長さ指定のブロックを取り込んでハッシュする（32 ビット）
 ******************************************************************/
int FNV512blockin ( FNV512context * const ctx,
                    const void *vin,
                    long int length ) {
    const uint8_t *in = (const uint8_t*)vin;
    uint32_t temp[FNV512size/2];
    uint32_t temp2[11];
    int i;

    if ( !ctx || !in )
        return fnvNull;
    if ( length < 0 )
        return fnvBadParam;
   switch ( ctx->Computed ) {
        case FNVinited+FNV512state:
            ctx->Computed = FNVcomputed+FNV512state;
            break;
        case FNVcomputed+FNV512state:
            break;
        default:
            return fnvStateError;
    }
    for ( i=0; i<FNV512size/2; ++i )
        temp[i] = ctx->Hash[i];  // temp にコピーする
    for ( ; length > 0; length-- ) {
        /* temp = FNV512prime * ( temp ^ *in++ ); */
        temp[FNV512size/2-1] ^= *in++;
        for ( i=0; i<11; ++i )
            temp2[10-i] = temp[FNV512size/2-1-i] << FNV512shift;
        for ( i=0; i<FNV512size/2; ++i )
            temp[i] *= FNV512primeX;
        for ( i=0; i<11; ++i )
            temp[i] += temp2[i];
        for ( i=FNV512size/2-1; i>0; --i ) {
            temp[i-1] += temp[i] >> 16; // 桁上がりを伝播する
            temp[i] &= 0xFFFF;
        }
    }   /* for length の終わり */
    for ( i=0; i<FNV512size/2; ++i )
        ctx->Hash[i] = (uint16_t)temp[i];  // hash に書き戻す
    return fnvSuccess;
}   /* FNV512blockin の終わり */

/* ゼロを含まずにゼロ終端文字列を取り込んでハッシュする（32 ビット）
 ******************************************************************/
int FNV512stringin ( FNV512context * const ctx, const char *in ) {
    uint32_t temp[FNV512size/2];
    uint32_t temp2[11];
    int i;
    uint8_t ch;

    if ( !ctx || !in )
        return fnvNull;
    switch ( ctx->Computed ) {
        case FNVinited+FNV512state:
            ctx->Computed = FNVcomputed+FNV512state;
            break;
        case FNVcomputed+FNV512state:
            break;
        default:
             return fnvStateError;
    }
    for ( i=0; i<FNV512size/2; ++i )
         temp[i] = ctx->Hash[i];  // temp にコピーする
    while ( (ch = (uint8_t)*in++) ) {
        /* temp = FNV512prime * ( temp ^ *in++ ); */
        temp[FNV512size/2-1] ^= ch;
        for ( i=0; i<11; ++i )
            temp2[10-i] = temp[FNV512size/2-1-i] << FNV512shift;
        for ( i=0; i<FNV512size/2; ++i )
            temp[i] *= FNV512primeX;
        for ( i=0; i<11; ++i )
            temp[i] += temp2[i];
        for ( i=FNV512size/2-1; i>0; --i ) {
            temp[i-1] += temp[i] >> 16; // 桁上がりを伝播する
            temp[i] &= 0xFFFF;
        }
    }
    for ( i=0; i<FNV512size/2; ++i )
        ctx->Hash[i] = temp[i];  // hash に書き戻す
    return fnvSuccess;
}   /* FNV512stringin の終わり */

/* ハッシュを返す（32 ビット）
 ******************************************************************/
int FNV512result ( FNV512context * const ctx,
                   uint8_t out[FNV512size] ) {
    if ( !ctx || !out )
        return fnvNull;
    if ( ctx->Computed != FNVcomputed+FNV512state )
        return fnvStateError;
    for ( int i=0; i<FNV512size/2; ++i ) {
        out[2*i] = ctx->Hash[i] >> 8;
        out[2*i+1] = ctx->Hash[i];
        ctx->Hash[i] = 0;
    }
    ctx->Computed = FNVemptied+FNV512state;
    return fnvSuccess;
}   /* FNV512result の終わり */

#endif    /*  FNV_64bitIntegers */
