#ifndef _FNV1024_H_
#define _FNV1024_H_

/*
 *  説明:
 *      このファイルは、1024 ビット版の
 *      FNV-1a 非暗号学的ハッシュアルゴリズムのヘッダーを提供する。
 */

#include "FNVconfig.h"
#include "FNVErrorCodes.h"

#include <stdint.h>
#define FNV1024size (1024/8)

/* ISO 標準の stdint.h ヘッダーファイルがない場合は、
 * 次の型を typedef する必要がある:
 *
 *    型                意味
 *  uint64_t    符号なし 64 ビット整数（ifdef FNV_64bitIntegers）
 *  uint32_t    符号なし 32 ビット整数
 *  uint16_t    符号なし 16 ビット整数
 *  uint8_t     符号なし 8 ビット整数（つまり unsigned char）
 */

/*
 *  この構造体は FNV1024 ハッシュのコンテキスト情報を保持する
 */
#ifdef FNV_64bitIntegers
    /* 64 ビット整数がサポートされている場合の版 */
typedef struct FNV1024context_s {
        int Computed;  /* 状態 */
        uint32_t Hash[FNV1024size/4];
} FNV1024context;

#else
    /* 64 ビット整数がサポートされていない場合の版 */
typedef struct FNV1024context_s {
        int Computed;  /* 状態 */
        uint16_t Hash[FNV1024size/2];
} FNV1024context;

#endif /* FNV_64bitIntegers */

/*  関数プロトタイプ:
 *
 *    FNV1024string: 終端のゼロを含まずに
 *                   ゼロ終端文字列をハッシュする
 *    FNV1024stringBasis: offset_basis パラメーターも受け取る
 *
 *    FNV1024block: 指定された長さのバイトベクターをハッシュする
 *    FNV1024blockBasis: offset_basis パラメーターも受け取る
 *
 *    FNV1024file: ファイルの内容をハッシュする
 *    FNV1024fileBasis: offset_basis パラメーターも受け取る
 *
 *    FNV1024init: FNV1024 コンテキストを初期化する
 *    FNV1024initBasis: 与えられた基数で FNV1024 コンテキストを
 *                      初期化する（128 バイトのベクター）
 *    FNV1024blockin: 指定された長さのバイトベクターを取り込んでハッシュする
 *    FNV1024stringin: 終端のゼロを含まずに
 *                     ゼロ終端文字列を取り込んでハッシュする
 *    FNV1024filein: ファイルの内容を取り込んでハッシュする
 *    FNV1024result: ハッシュ値を返す
 *
 *    ハッシュは 8 ビットの符号なし整数の配列として返される
 */

#ifdef __cplusplus
extern "C" {
#endif

/* FNV1024 */
extern int FNV1024string ( const char *in,
                           uint8_t out[FNV1024size] );
extern int FNV1024stringBasis ( const char *in,
                                uint8_t out[FNV1024size],
                                const uint8_t basis[FNV1024size] );
extern int FNV1024block ( const void *vin,
                          long int length,
                          uint8_t out[FNV1024size] );
extern int FNV1024blockBasis ( const void *vin,
                               long int length,
                               uint8_t out[FNV1024size],
                               const uint8_t basis[FNV1024size] );
extern int FNV1024file ( const char *fname,
                         uint8_t out[FNV1024size] );
extern int FNV1024fileBasis ( const char *fname,
                              uint8_t out[FNV1024size],
                              const uint8_t basis[FNV1024size] );
extern int FNV1024init ( FNV1024context * const );
extern int FNV1024initBasis ( FNV1024context * const,
                              const uint8_t basis[FNV1024size] );
extern int FNV1024blockin ( FNV1024context * const,
                            const void *vin,
                            long int length );
extern int FNV1024stringin ( FNV1024context * const,
                            const char *in );
extern int FNV1024filein ( FNV1024context * const,
                           const char *fname );
extern int FNV1024result ( FNV1024context * const,
                           uint8_t out[FNV1024size] );

#ifdef __cplusplus
}
#endif

#endif /* _FNV1024_H_ */

